screenPanels.initJs:
function(container, apiUrl, tables) {
  let loginAttempts = 0;
  const maxAttempts = 5;
  let isAccountLocked = false;

  // DOM要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  const loginBtn = container.querySelector('#login-btn');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  // エラーメッセージ非表示関数
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // バリデーション関数
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value;

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    if (isAccountLocked) {
      showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
      return;
    }

    try {
      // ユーザーテーブルから認証情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
        return;
      }

      // ユーザー認証
      const user = users.find(u => u.ユーザー名 === userId && u.有効フラグ === true);

      if (!user) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      // ここでは簡易的にプレーンテキストで比較
      if (user.パスワードハッシュ !== password) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // ログイン成功
      loginAttempts = 0; // リセット

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション情報を保存
      const sessionData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        displayName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('workTimeSession', JSON.stringify(sessionData));
      } else {
        sessionStorage.setItem('workTimeSession', JSON.stringify(sessionData));
      }

      // メイン画面（工数記録画面）に遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
    }
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value;
    const rememberMe = rememberMeCheckbox.checked;

    loginBtn.disabled = true;
    loginBtn.textContent = 'ログイン中...';

    await handleLogin(userId, password, rememberMe);

    loginBtn.disabled = false;
    loginBtn.textContent = 'ログイン';
  });

  // パスワード忘れリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では別画面を作成）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // ログイン状態チェック（ページ読み込み時）
  function checkExistingSession() {
    const sessionData = localStorage.getItem('workTimeSession') || sessionStorage.getItem('workTimeSession');
    if (sessionData) {
      try {
        const session = JSON.parse(sessionData);
        // セッションが有効な場合は自動的にメイン画面に遷移
        window.showScreen("scr-1778907133295");
      } catch (error) {
        // セッションデータが破損している場合はクリア
        localStorage.removeItem('workTimeSession');
        sessionStorage.removeItem('workTimeSession');
      }
    }
  }

  // 初期化時にセッションチェック
  checkExistingSession();

  // ホバー効果
  loginBtn.addEventListener('mouseenter', () => {
    if (!loginBtn.disabled) {
      loginBtn.style.background = 'var(--primary-hover)';
    }
  });

  loginBtn.addEventListener('mouseleave', () => {
    if (!loginBtn.disabled) {
      loginBtn.style.background = 'var(--primary)';
    }
  });

  // フォーカス時のエラーメッセージクリア
  userIdInput.addEventListener('focus', hideError);
  passwordInput.addEventListener('focus', hideError);
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let elapsedInterval = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let pauseRecords = [];

  // 作業項目マスタのテーブルインデックス
  const WORK_ITEMS_TABLE = 3;
  const WORK_RECORDS_TABLE = 1;
  const PAUSE_RECORDS_TABLE = 2;

  // 現在時刻更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleTimeString('ja-JP', { hour12: false });
    container.querySelector('#current-time').textContent = timeStr;

    const dateStr = now.toLocaleDateString('ja-JP', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric', 
      weekday: 'short' 
    });
    container.querySelector('#current-date').textContent = dateStr;
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (pauseStartTime) {
      // 中断中の場合は中断開始時点までの時間
      elapsed = pauseStartTime - startTime - totalPauseTime;
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // 作業状態更新
  function updateWorkStatus(status, color = 'rgba(128,128,128,0.2)') {
    const statusEl = container.querySelector('#work-status');
    statusEl.textContent = status;
    statusEl.style.background = color;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.classList.remove('hidden');
    setTimeout(() => errorEl.classList.add('hidden'), 5000);
  }

  // 作業項目読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(WORK_ITEMS_TABLE);
    if (!workItems) return;

    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
  }

  // 本日の作業履歴表示
  function renderTodayWorkList(records) {
    const tbody = container.querySelector('#today-work-list');
    const today = new Date().toISOString().split('T')[0];

    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toISOString().split('T')[0];
      return recordDate === today;
    }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

    if (todayRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 16px; color: var(--text-muted);">本日の作業履歴はありません</td></tr>';
      return;
    }

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { hour12: false, hour: '2-digit', minute: '2-digit' });
      const endTime = record.作業終了時刻? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', { hour12: false, hour: '2-digit', minute: '2-digit' }) : '作業中';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';

      return `
        <tr data-id="${record.作業記録ID}">
          <td style="padding: 6px 8px;">${startTime}</td>
          <td style="padding: 6px 8px;">${endTime}</td>
          <td style="padding: 6px 8px;">${record.作業内容 || record.プロジェクト名 || '-'}</td>
          <td style="padding: 6px 8px; text-align: right;">${workTime}</td>
        </tr>
      `;
    }).join('');
  }

  // 作業開始
  async function startWork() {
    const workItemId = container.querySelector('#work-item-select').value;
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    const workItems = await window.aivicApi.list(WORK_ITEMS_TABLE);
    const selectedItem = workItems?.find(item => item.作業項目ID === workItemId);

    startTime = new Date();
    totalPauseTime = 0;
    pauseRecords = [];
    pauseStartTime = null;

    // 作業記録を作成
    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業日: startTime.toISOString(),
      作業開始時刻: startTime.toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: '現場A', // 実際の実装では選択可能にする
      作業種別: selectedItem?.カテゴリ || '一般作業',
      作業内容: selectedItem?.作業項目名|| '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    currentWorkRecord = await window.aivicApi.save(WORK_RECORDS_TABLE, workRecord);
    if (!currentWorkRecord) {
      showError('作業記録の作成に失敗しました');
      return;
    }

    // UI更新
    updateWorkStatus('作業中', 'rgba(34,197,94,0.2)');
    container.querySelector('#btn-start-work').disabled = true;
    container.querySelector('#btn-end-work').disabled = false;
    container.querySelector('#btn-pause-work').disabled = false;
    container.querySelector('#work-item-select').disabled = true;

    // 経過時間更新開始
    elapsedInterval = setInterval(updateElapsedTime, 1000);
    updateElapsedTime();

    // 作業履歴を更新
    const records = await window.aivicApi.list(WORK_RECORDS_TABLE);
    if (records) renderTodayWorkList(records);
  }

  // 作業終了
  async function endWork() {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    const endTime = new Date();
    let totalWorkTime = endTime - startTime - totalPauseTime;

    // 中断中の場合は中断を終了
    if (pauseStartTime) {
      const pauseTime = endTime - pauseStartTime;
      totalPauseTime += pauseTime;

      // 中断記録を保存
      const pauseRecord = {
        作業記録ID: currentWorkRecord.作業記録ID,
        中断開始日時: pauseStartTime.toISOString(),
        中断終了日時: endTime.toISOString(),
        中断理由区分: '作業終了',
        中断理由詳細: '作業終了のため中断終了',
        中断時間: Math.floor(pauseTime / (1000 * 60)),
        対応状況: '解決済み',
        記録者ID: 'current-user-id'
      };

      await window.aivicApi.save(PAUSE_RECORDS_TABLE, pauseRecord);
      pauseStartTime = null;
    }

    // 作業記録を更新
    const workTimeMinutes = Math.floor(totalWorkTime / (1000 * 60));
    const memo = container.querySelector('#work-memo').value;

    const updatedRecord = {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTimeMinutes,
      進捗状況: '完了',
      備考: memo
    };

    await window.aivicApi.update(WORK_RECORDS_TABLE, currentWorkRecord.作業記録ID, updatedRecord);

    // リセット
    currentWorkRecord = null;
    startTime = null;
    totalPauseTime = 0;
    pauseRecords = [];

    if (elapsedInterval) {
      clearInterval(elapsedInterval);
      elapsedInterval = null;
    }

    // UI更新
    updateWorkStatus('完了', 'rgba(59,130,246,0.2)');
    container.querySelector('#btn-start-work').disabled = false;
    container.querySelector('#btn-end-work').disabled = true;
    container.querySelector('#btn-pause-work').disabled = true;
    container.querySelector('#work-item-select').disabled = false;
    container.querySelector('#elapsed-time').textContent = '00:00:00';
    container.querySelector('#work-memo').value = '';
    container.querySelector('#memo-count').textContent = '0';

    // 作業履歴を更新
    const records = await window.aivicApi.list(WORK_RECORDS_TABLE);
    if (records) renderTodayWorkList(records);
  }

  // 作業中断
  function pauseWork() {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    if (pauseStartTime) {
      showError('既に中断中です');
      return;
    }

    // 中断理由入力モーダルを表示
    container.querySelector('#pause-modal').classList.remove('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-reason').focus();
  }

  // 中断確定
  async function confirmPause() {
    const reason = container.querySelector('#pause-reason').value.trim();
    if (!reason) {
      showError('中断理由を入力してください');
      return;
    }

    if (reason.length > 500) {
      showError('中断理由は500文字以内で入力してください');
      return;
    }

    pauseStartTime = new Date();

    // UI更新
    updateWorkStatus('中断中', 'rgba(245,158,11,0.2)');
    container.querySelector('#pause-modal').classList.add('hidden');

    // 中断記録を保存（開始のみ）
    const pauseRecord = {
      作業記録ID: currentWorkRecord.作業記録ID,
      中断開始日時: pauseStartTime.toISOString(),
      中断理由区分: '一般',
      中断理由詳細: reason,
      対応状況: '対応中',
      記録者ID: 'current-user-id'
    };

    const savedPauseRecord = await window.aivicApi.save(PAUSE_RECORDS_TABLE, pauseRecord);
    if (savedPauseRecord) {
      pauseRecords.push(savedPauseRecord);
    }
  }

  // 作業再開
  async function resumeWork() {
    if (!pauseStartTime) return;

    const resumeTime = new Date();
    const pauseTime = resumeTime - pauseStartTime;
    totalPauseTime += pauseTime;

    // 最後の中断記録を更新
    const lastPauseRecord = pauseRecords[pauseRecords.length - 1];
    if (lastPauseRecord) {
      await window.aivicApi.update(PAUSE_RECORDS_TABLE, lastPauseRecord.中断記録ID, {
        中断終了日時: resumeTime.toISOString(),
        中断時間: Math.floor(pauseTime / (1000 * 60)),
        対応状況: '解決済み'
      });
    }

    pauseStartTime = null;
    updateWorkStatus('作業中', 'rgba(34,197,94,0.2)');
  }

  // 保存
  async function saveWork() {
    const memo = container.querySelector('#work-memo').value;

    if (currentWorkRecord && memo) {
      await window.aivicApi.update(WORK_RECORDS_TABLE, currentWorkRecord.作業記録ID, {
        備考: memo
      });
    }

    // 作業履歴を更新
    const records = await window.aivicApi.list(WORK_RECORDS_TABLE);
    if (records) renderTodayWorkList(records);
  }

  // キャンセル
  function cancelWork() {
    if (currentWorkRecord) {
      if (!confirm('作業中です。キャンセルしますか？未保存のデータは失われます。')) {
        return;
      }

      // 作業をリセット
      if (elapsedInterval) {
        clearInterval(elapsedInterval);
        elapsedInterval = null;
      }

      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseRecords = [];
      pauseStartTime = null;

      // UI更新
      updateWorkStatus('待機中', 'rgba(128,128,128,0.2)');
      container.querySelector('#btn-start-work').disabled = false;
      container.querySelector('#btn-end-work').disabled = true;
      container.querySelector('#btn-pause-work').disabled = true;
      container.querySelector('#work-item-select').disabled = false;
      container.querySelector('#elapsed-time').textContent = '00:00:00';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#memo-count').textContent = '0';
    }
  }

  // メモ文字数カウント
  function updateMemoCount() {
    const memo = container.querySelector('#work-memo').value;
    const count = memo.length;
    container.querySelector('#memo-count').textContent = count;

    if (count > 500) {
      container.querySelector('#work-memo').value = memo.substring(0, 500);
      container.querySelector('#memo-count').textContent = '500';
    }
  }

  // 初期化
  async function init() {
    // 現在時刻更新開始
    updateCurrentTime();
    setInterval(updateCurrentTime, 1000);

    // 作業項目読み込み
    await loadWorkItems();

    // 本日の作業履歴表示
    const records = await window.aivicApi.list(WORK_RECORDS_TABLE);
    if (records) renderTodayWorkList(records);

    // イベントリスナー設定
    container.querySelector('#btn-start-work').addEventListener('click', startWork);
    container.querySelector('#btn-end-work').addEventListener('click', endWork);
    container.querySelector('#btn-pause-work').addEventListener('click', pauseWork);
    container.querySelector('#btn-confirm-pause').addEventListener('click', confirmPause);
    container.querySelector('#btn-cancel-pause').addEventListener('click', () => {
      container.querySelector('#pause-modal').classList.add('hidden');
    });
    container.querySelector('#btn-save').addEventListener('click', saveWork);
    container.querySelector('#btn-cancel').addEventListener('click', cancelWork);
    container.querySelector('#work-memo').addEventListener('input', updateMemoCount);

    // 画面遷移
    container.querySelector('#btn-work-history').addEventListener('click', () => {
      window.showScreen("scr-1778907145716");
    });
    container.querySelector('#btn-emergency-report').addEventListener('click', () => {
      window.showScreen("scr-1778907330826");
    });

    // 作業状態クリックで再開
    container.querySelector('#work-status').addEventListener('click', () => {
      if (pauseStartTime) {
        resumeWork();
      }
    });

    // モーダル外クリックで閉じる
    container.querySelector('#pause-modal').addEventListener('click', (e) => {
      if (e.target.id === 'pause-modal') {
        container.querySelector('#pause-modal').classList.add('hidden');
      }
    });
  }

  init();
}

function(container, apiUrl, tables) {
  let currentWorkHistoryData = [];
  let selectedRowId = null;

  // 作業項目マスタの取得とドロップダウン設定
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const select = container.querySelector("#filter-work-item");
      if (workItems && workItems.length > 0) {
        workItems.forEach(item => {
          const option = document.createElement("option");
          option.value = item.作業項目名 || item.name || "";
          option.textContent = item.作業項目名 || item.name || "";
          select.appendChild(option);
        });
      }
    } catch (error) {
      console.error("作業項目の読み込みに失敗しました:", error);
    }
  }

  // 中断回数を計算する関数
  async function getInterruptionCount(workRecordId) {
    try {
      const interruptions = await window.aivicApi.list(2); // 中断記録
      if (!interruptions) return 0;
      return interruptions.filter(int => int.作業記録ID === workRecordId).length;
    } catch (error) {
      return 0;
    }
  }

  // テーブル再描画関数
  async function renderRows(rows) {
    const tbody = container.querySelector("#work-history-tbody");
    const noResults = container.querySelector("#no-results");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");

    // 中断回数を並列で取得
    const rowsWithInterruptions = await Promise.all(
      rows.map(async (row) => {
        const interruptionCount = await getInterruptionCount(row.id || row.作業記録ID);
        return { ...row, interruptionCount };
      })
    );

    tbody.innerHTML = rowsWithInterruptions.map(row => {
      const workDate = row.作業日 ? new Date(row.作業日).toLocaleDateString('ja-JP') : "";
      const startTime = row.作業開始時刻 ? new Date(row.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : "";
      const endTime = row.作業終了時刻 ? new Date(row.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : "";
      const workTime = row.作業時間 ? `${Math.floor(row.作業時間 / 60)}時間${row.作業時間 % 60}分` : "";
      const status = row.進捗状況 || "";
      const workItem = row.作業種別 || "";

      return `
        <tr data-id="${row.id || row.作業記録ID}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItem}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${row.interruptionCount}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <span style="padding: 2px 8px; border-radius: 4px; font-size: 11px; background: ${status === '完了' ? 'rgba(100,200,100,0.2)' : status === '作業中' ? 'rgba(100,150,255,0.2)' : 'rgba(255,150,100,0.2)'}; color: var(--text);">
              ${status}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary select-btn" data-id="${row.id || row.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">選択</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // 日付バリデーション関数
  function validateDateRange(startDate, endDate) {
    if (!startDate && !endDate) {
      return { valid: false, message: "日付範囲を選択してください" };
    }

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(23, 59, 59, 999);

      if (start > today || end > today) {
        return { valid: false, message: "未来の日付は選択できません" };
      }

      if (start > end) {
        return { valid: false, message: "開始日は終了日より前の日付を入力してください" };
      }

      const oneYearAgo = new Date();
      oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

      if (start < oneYearAgo) {
        return { valid: false, message: "1年以上前の期間は選択できません" };
      }
    }

    return { valid: true };
  }

  // フィルター処理関数
  function filterData(data) {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    return data.filter(row => {
      // 日付フィルター
      if (startDate || endDate) {
        const workDate = row.作業日 ? new Date(row.作業日) : null;
        if (!workDate) return false;

        if (startDate && workDate < new Date(startDate)) return false;
        if (endDate && workDate > new Date(endDate + "T23:59:59")) return false;
      }

      // 作業項目フィルター
      if (workItem && (row.作業種別 || "") !== workItem) return false;

      // 状況フィルター
      if (status && (row.進捗状況 || "") !== status) return false;

      return true;
    });
  }

  // CSVエクスポート関数
  function exportToCSV(data) {
    const headers = ["作業日時", "作業項目名", "開始時刻", "終了時刻", "作業時間", "中断回数", "状況"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...data.map(row => {
        const workDate = row.作業日 ? new Date(row.作業日).toLocaleDateString('ja-JP') : "";
        const startTime = row.作業開始時刻 ? new Date(row.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : "";
        const endTime = row.作業終了時刻 ? new Date(row.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : "";
        const workTime = row.作業時間 ? `${Math.floor(row.作業時間 / 60)}時間${row.作業時間 % 60}分` : "";
        const status = row.進捗状況 || "";
        const workItem = row.作業種別 || "";

        return [
          `"${workDate}"`,
          `"${workItem}"`,
          `"${startTime}"`,
          `"${endTime}"`,
          `"${workTime}"`,
          `"${row.interruptionCount || 0}"`,
          `"${status}"`
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "work_history_export.csv";
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const workHistoryData = await window.aivicApi.list(1); // 作業記録
      if (workHistoryData) {
        currentWorkHistoryData = workHistoryData.sort((a, b) => {
          const dateA = new Date(a.作業日 || a.作業開始時刻);
          const dateB = new Date(b.作業日 || b.作業開始時刻);
          return dateB - dateA; // 新しい順
        });
        await renderRows(currentWorkHistoryData);
      }
    } catch (error) {
      console.error("データの読み込みに失敗しました:", error);
      showError("データの読み込みに失敗しました");
    }
  }

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;

    const validation = validateDateRange(startDate, endDate);
    if (!validation.valid) {
      showError(validation.message);
      return;
    }

    try {
      const allData = await window.aivicApi.list(1);
      if (allData) {
        const filteredData = filterData(allData);
        currentWorkHistoryData = filteredData.sort((a, b) => {
          const dateA = new Date(a.作業日 || a.作業開始時刻);
          const dateB = new Date(b.作業日 || b.作業開始時刻);
          return dateB - dateA;
        });
        await renderRows(currentWorkHistoryData);
      }
    } catch (error) {
      console.error("検索に失敗しました:", error);
      showError("検索に失敗しました");
    }
  });

  // リセットボタンイベント
  container.querySelector("#btn-reset").addEventListener("click", async () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    selectedRowId = null;
    await loadInitialData();
  });

  // 検索条件クリアボタンイベント
  container.querySelector("#btn-clear-filters").addEventListener("click", async () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    selectedRowId = null;
    await loadInitialData();
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    if (currentWorkHistoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    // 中断回数を含むデータを準備
    const dataWithInterruptions = await Promise.all(
      currentWorkHistoryData.map(async (row) => {
        const interruptionCount = await getInterruptionCount(row.id || row.作業記録ID);
        return { ...row, interruptionCount };
      })
    );

    exportToCSV(dataWithInterruptions);
  });

  // 行選択イベント（イベントデリゲーション）
  container.addEventListener("click", (e) => {
    const selectBtn = e.target.closest(".select-btn");
    if (selectBtn) {
      selectedRowId = selectBtn.dataset.id;
      // 選択状態の視覚的フィードバック
      container.querySelectorAll("tr").forEach(tr => tr.style.background = "");
      const selectedRow = container.querySelector(`tr[data-id="${selectedRowId}"]`);
      if (selectedRow) {
        selectedRow.style.background = "rgba(255,255,255,0.05)";
      }
    }
  });

  // 詳細確認ボタンイベント
  container.querySelector("#btn-detail").addEventListener("click", () => {
    if (!selectedRowId) {
      showError("詳細を確認する作業履歴を選択してください");
      return;
    }
    window.showScreen("scr-1778907367889");
  });

  // データ抽出ボタンイベント
  container.querySelector("#btn-export-data").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  // 戻るボタンイベント
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期化処理
  loadWorkItems();
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let selectedLogId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#anomaly-log-tbody");
    const noDataMessage = container.querySelector("#no-data-message");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noDataMessage.classList.remove("hidden");
      return;
    }

    noDataMessage.classList.add("hidden");
    tbody.innerHTML = rows.map(r => {
      const detectionTime = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : '';
      const workerName = r.作業員名 || '';
      const anomalyType = r.異常値種別 || '';
      const detectionItem = r.検出項目 || '';
      const detectionValue = r.検出値 || '';
      const threshold = r.閾値 || '';
      const importance = r.重要度 || '';
      const status = r.確認状況 || '';

      let statusBadge = '';
      if (status === '未確認') {
        statusBadge = `<span style="background: #ff6a00; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
      } else if (status === '確認済み') {
        statusBadge = `<span style="background: #0066cc; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
      } else if (status === '対応済み') {
        statusBadge = `<span style="background: #00aa44; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
      } else {
        statusBadge = `<span style="color: var(--text-muted); font-size: 11px;">${status}</span>`;
      }

      let importanceBadge = '';
      if (importance === '高') {
        importanceBadge = `<span style="background: #cc0000; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${importance}</span>`;
      } else if (importance === '中') {
        importanceBadge = `<span style="background: #ff6a00; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${importance}</span>`;
      } else if (importance === '低') {
        importanceBadge = `<span style="background: #666; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${importance}</span>`;
      } else {
        importanceBadge = `<span style="color: var(--text-muted); font-size: 11px;">${importance}</span>`;
      }

      return `<tr data-id="${r.異常値検出ログID || r.id}" style="cursor: pointer;">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${detectionTime}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workerName}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${anomalyType}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${detectionItem}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${detectionValue}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${threshold}</td>
        <td style="padding: 6px 10px;">${importanceBadge}</td>
        <td style="padding: 6px 10px;">${statusBadge}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary detail-btn" data-id="${r.異常値検出ログID || r.id}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データを即座に描画
  currentData = tables[4]?.records || [];
  renderRows(currentData);

  // 最新データを取得して描画
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      renderRows(rows);
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const anomalyType = container.querySelector("#filter-anomaly-type").value;
    const workerName = container.querySelector("#filter-worker-name").value.trim();
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    // 日付形式チェック
    if (startDate && !isValidDateTime(startDate)) {
      alert("正しい日付形式で入力してください（YYYY-MM-DD HH:MM）");
      return;
    }
    if (endDate && !isValidDateTime(endDate)) {
      alert("正しい日付形式で入力してください（YYYY-MM-DD HH:MM）");
      return;
    }

    const allRows = await window.aivicApi.list(4);
    if (!allRows) return;

    let filteredRows = allRows.filter(r => {
      // 日付フィルター
      if (startDate) {
        const detectionTime = new Date(r.検出日時);
        const filterStart = new Date(startDate);
        if (detectionTime < filterStart) return false;
      }
      if (endDate) {
        const detectionTime = new Date(r.検出日時);
        const filterEnd = new Date(endDate);
        if (detectionTime > filterEnd) return false;
      }

      // 異常値タイプフィルター
      if (anomalyType && r.異常値種別 !== anomalyType) return false;

      // 作業員名フィルター
      if (workerName && !(r.作業員名 || '').includes(workerName)) return false;

      // 作業項目フィルター（検出対象レコードから推測）
      if (workItem) {
        // 実際の実装では作業記録テーブルとの結合が必要だが、
        // ここでは簡易的に対応メモに含まれるかで判定
        if (!(r.対応メモ || '').includes(workItem)) return false;
      }

      // ステータスフィルター
      if (status && r.確認状況 !== status) return false;

      return true;
    });

    currentData = filteredRows;
    renderRows(filteredRows);
  });

  // フィルタークリアボタン
  container.querySelector("#btn-clear-filter").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-anomaly-type").value = "";
    container.querySelector("#filter-worker-name").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";

    renderRows(currentData);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(4);
    if (!allRows || allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["検出日時", "作業員名", "異常値タイプ", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
    const csvData = [headers.join(",")];

    allRows.forEach(r => {
      const row = [
        `"${new Date(r.検出日時).toLocaleString('ja-JP')}"`,
        `"${r.作業員名 || ''}"`,
        `"${r.異常値種別 || ''}"`,
        `"${r.検出項目 || ''}"`,
        `"${r.検出値 || ''}"`,
        `"${r.閾値 || ''}"`,
        `"${r.重要度 || ''}"`,
        `"${r.確認状況 || ''}"`,
        `"${(r.対応メモ || '').replace(/"/g, '""')}"`
      ];
      csvData.push(row.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `anomaly_detection_log_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細表示・行クリック処理
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const row = e.target.closest("tr[data-id]");

    if (detailBtn || (row && !e.target.closest("button"))) {
      const id = detailBtn ? detailBtn.dataset.id : row.dataset.id;
      const logData = currentData.find(r => (r.異常値検出ログID || r.id) === id);

      if (logData) {
        selectedLogId = id;
        showDetail(logData);
      }
    }
  });

  // 詳細表示関数
  function showDetail(logData) {
    const detailArea = container.querySelector("#detail-area");
    detailArea.classList.remove("hidden");

    container.querySelector("#detail-detection-time").textContent = 
      logData.検出日時 ? new Date(logData.検出日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-worker-name").textContent = logData.作業員名 || '';
    container.querySelector("#detail-anomaly-type").textContent = logData.異常値種別 || '';
    container.querySelector("#detail-detection-item").textContent = logData.検出項目 || '';
    container.querySelector("#detail-values").textContent = 
      `${logData.検出値 || ''} / ${logData.閾値 || ''}`;
    container.querySelector("#detail-importance").textContent = logData.重要度 || '';
    container.querySelector("#detail-status").value = logData.確認状況 || '未確認';
    container.querySelector("#detail-memo").value = logData.対応メモ || '';

    updateMemoCount();
  }

  // 詳細エリアを閉じる
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    container.querySelector("#detail-area").classList.add("hidden");
    selectedLogId = null;
  });

  // 対応状況更新
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const newStatus = container.querySelector("#detail-status").value;
    const updateData = {
      確認状況: newStatus,
      確認日時: new Date().toISOString(),
      確認者ID: "current-user-id" // 実際の実装では現在のユーザーIDを取得
    };

    try {
      const updated = await window.aivicApi.update(4, selectedLogId, updateData);
      if (updated) {
        alert("対応状況を更新しました");
        // データを再取得して表示を更新
        const refreshedData = await window.aivicApi.list(4);
        if (refreshedData) {
          currentData = refreshedData;
          renderRows(currentData);
        }
      } else {
        alert("対応状況の更新に失敗しました");
      }
    } catch (error) {
      alert("ネットワークエラーが発生しました。再試行してください。");
    }
  });

  // コメント保存
  container.querySelector("#btn-save-memo").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const memo = container.querySelector("#detail-memo").value;
    if (memo.length > 1000) {
      alert("コメントは1000文字以内で入力してください");
      return;
    }

    const updateData = {
      対応メモ: memo,
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(4, selectedLogId, updateData);
    if (updated) {
      alert("コメントを保存しました");
      // データを再取得して表示を更新
      const refreshedData = await window.aivicApi.list(4);
      if (refreshedData) {
        currentData = refreshedData;
        renderRows(currentData);
      }
    } else {
      alert("コメントの保存に失敗しました");
    }
  });

  // メモ文字数カウント
  function updateMemoCount() {
    const memo = container.querySelector("#detail-memo");
    const count = container.querySelector("#memo-count");
    count.textContent = `${memo.value.length}/1000`;
  }

  container.querySelector("#detail-memo").addEventListener("input", updateMemoCount);

  // 日付形式チェック関数
  function isValidDateTime(dateTimeString) {
    const date = new Date(dateTimeString);
    return date instanceof Date && !isNaN(date);
  }
}

