      return `
        <div style="padding: 8px; background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 4px; margin-bottom: 6px;">
          <div style="font-size: 12px; font-weight: 500;">${work.作業項目名 || '作業項目不明'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">
            開始: ${startTime.getHours()}:${String(startTime.getMinutes()).padStart(2, '0')} | 
            経過: ${hours}時間${minutes}分
          </div>
          <div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所 || '未設定'}</div>
        </div>
      `;
    }).join('');
  }

  // 中断中作業を描画
  function renderSuspendedWorks() {
    const container_el = container.querySelector('#suspended-works');
    if (suspendedWorks.length === 0) {
      container_el.innerHTML = '<div style="padding: 8px; background: rgba(0,0,0,0.15); border-radius: 4px; font-size: 12px; color: var(--text-muted); text-align: center;">中断中の作業はありません</div>';
      return;
    }

    container_el.innerHTML = suspendedWorks.map(work => {
      return `
        <div style="padding: 8px; background: rgba(251, 191, 36, 0.1); border: 1px solid rgba(251, 191, 36, 0.3); border-radius: 4px; margin-bottom: 6px;">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-size: 12px; font-weight: 500;">${work.作業項目名 || '作業項目不明'}</div>
              <div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所 || '未設定'}</div>
            </div>
            <button class="action-btn resume-work-btn" data-id="${work.id}" style="padding: 4px 8px; font-size: 11px;">再開</button>
          </div>
        </div>
      `;
    }).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.style.display = 'block';
    setTimeout(() => {
      errorEl.style.display = 'none';
    }, 5000);
  }

  // 確認ダイアログ表示
  function showConfirmDialog(title, message) {
    return new Promise((resolve) => {
      const dialog = container.querySelector('#confirm-dialog');
      const titleEl = dialog.querySelector('#dialog-title');
      const messageEl = dialog.querySelector('#dialog-message');
      const confirmBtn = dialog.querySelector('#dialog-confirm');
      const cancelBtn = dialog.querySelector('#dialog-cancel');

      titleEl.textContent = title;
      messageEl.textContent = message;
      dialog.classList.remove('hidden');

      const handleConfirm = () => {
        dialog.classList.add('hidden');
        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
        resolve(true);
      };

      const handleCancel = () => {
        dialog.classList.add('hidden');
        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
        resolve(false);
      };

      confirmBtn.addEventListener('click', handleConfirm);
      cancelBtn.addEventListener('click', handleCancel);
    });
  }

  // バリデーション
  function validateWorkStart() {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value.trim();
    const notes = container.querySelector('#work-notes').value.trim();

    if (!workItemId) {
      showError('作業項目を選択してください');
      return false;
    }

    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return false;
    }

    // 作業場所の不正文字チェック
    if (workLocation && /<script|javascript:|on\w+=/i.test(workLocation)) {
      showError('作業場所に不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業項目マスタを読み込み
      const workItemsData = await window.aivicApi.list(3); // 作業項目マスタのテーブルインデックス
      if (workItemsData) {
        workItems = workItemsData.filter(item => item.有効フラグ);
        renderWorkItems();
      }

      // 作業記録を読み込み（進行中・中断中の作業を抽出）
      const workRecords = await window.aivicApi.list(1); // 作業記録のテーブルインデックス
      if (workRecords) {
        activeWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && record.進捗状況 === '作業中'
        );
        suspendedWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && record.進捗状況 === '中断'
        );

        // 作業項目名を付与
        activeWorks.forEach(work => {
          const workItem = workItems.find(item => item.id === work.プロジェクト名);
          work.作業項目名 = workItem ? workItem.作業項目名 : work.プロジェクト名;
        });
        suspendedWorks.forEach(work => {
          const workItem = workItems.find(item => item.id === work.プロジェクト名);
          work.作業項目名 = workItem ? workItem.作業項目名 : work.プロジェクト名;
        });

        renderActiveWorks();
        renderSuspendedWorks();
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 文字数カウンター更新
  function updateNotesCounter() {
    const notes = container.querySelector('#work-notes').value;
    const counter = container.querySelector('#notes-counter');
    counter.textContent = notes.length;
  }

  // イベントリスナー設定
  container.querySelector('#work-notes').addEventListener('input', updateNotesCounter);

  // 記録開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    if (!validateWorkStart()) return;

    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value.trim();
    const notes = container.querySelector('#work-notes').value.trim();
    const selectedWorkItem = workItems.find(item => item.id === workItemId);

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: workItemId,
      作業場所: workLocation || '',
      作業種別: selectedWorkItem ? selectedWorkItem.カテゴリ : '',
      作業内容: selectedWorkItem ? selectedWorkItem.作業項目名 : '',
      進捗状況: '作業中',
      備考: notes,
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: currentUser.id
    };

    try {
      const saved = await window.aivicApi.save(1, workRecord);
      if (saved) {
        // フォームクリア
        container.querySelector('#work-item-select').value = '';
        container.querySelector('#work-location').value = '';
        container.querySelector('#work-notes').value = '';
        updateNotesCounter();

        // データ再読み込み
        await loadInitialData();

        alert('工数記録を開始しました');
      }
    } catch (error) {
      showError('工数記録の開始に失敗しました');
    }
  });

  // 中断作業再開
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-work-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      const work = suspendedWorks.find(w => w.id === workId);

      if (!work) {
        showError('指定された作業が見つかりません');
        return;
      }

      if (activeWorks.length > 0) {
        showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
        return;
      }

      const confirmed = await showConfirmDialog('作業再開', `「${work.作業項目名}」の作業を再開しますか？`);
      if (!confirmed) return;

      try {
        const updated = await window.aivicApi.update(1, workId, {
          進捗状況: '作業中',
          作業開始時刻: new Date().toISOString() // 再開時刻で更新
        });

        if (updated) {
          await loadInitialData();
          alert('作業を再開しました');
        }
      } catch (error) {
        showError('作業の再開に失敗しました');
      }
    }
  });

  // 工数入力画面への遷移
  container.querySelector('#btn-work-input').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });

  // ログアウト
  container.querySelector('#btn-logout').addEventListener('click', async () => {
    const confirmed = await showConfirmDialog('ログアウト', 'ログアウトしますか？');
    if (confirmed) {
      window.location.href = './login.html';
    }
  });

  // 設定メニュー
  container.querySelector('#btn-settings').addEventListener('click', () => {
    alert('設定画面は準備中です');
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000); // 1分ごとに時刻更新
  loadInitialData();

  // 進行中作業の経過時間を1分ごとに更新
  setInterval(() => {
    if (activeWorks.length > 0) {
      renderActiveWorks();
    }
  }, 60000);
}

function(container, apiUrl, tables) {
  // 現在の作業記録データを取得（最新の未完了記録を想定）
  let currentWorkRecord = null;

  // 初期データの設定
  async function initializeData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords && workRecords.length > 0) {
        // 最新の未完了記録を取得
        currentWorkRecord = workRecords.find(r => r.作業終了時刻 === null || r.進捗状況 === '作業中') || workRecords[workRecords.length - 1];

        if (currentWorkRecord) {
          // 時刻情報の表示
          const startTime = new Date(currentWorkRecord.作業開始時刻);
          const endTime = currentWorkRecord.作業終了時刻? new Date(currentWorkRecord.作業終了時刻) : new Date();

          container.querySelector('#work-item-name').textContent = currentWorkRecord.作業種別 || '作業項目';
          container.querySelector('#start-time').textContent = formatTime(startTime);
          container.querySelector('#end-time').textContent = formatTime(endTime);

          // 作業時間の計算
          const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));

          // 中断時間の取得
          const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
          let breakMinutes = 0;
          if (breakRecords) {
            breakMinutes = breakRecords
              .filter(b => b.作業記録ID === currentWorkRecord.作業記録ID && b.中断終了日時)
              .reduce((sum, b) => sum + (b.中断時間 || 0), 0);
          }

          const actualMinutes = totalMinutes - breakMinutes;

          container.querySelector('#total-time').textContent = formatDuration(totalMinutes);
          container.querySelector('#break-time').textContent = formatDuration(breakMinutes);
          container.querySelector('#actual-work-time').textContent = formatDuration(actualMinutes);
        }
      }
    } catch (error) {
      console.error('データ初期化エラー:', error);
    }
  }

  // 時刻フォーマット関数
  function formatTime(date) {
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 時間フォーマット関数
  function formatDuration(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 文字数カウント
  const workMemo = container.querySelector('#work-memo');
  const memoCount = container.querySelector('#memo-count');
  const issueContent = container.querySelector('#issue-content');
  const issueCount = container.querySelector('#issue-count');

  workMemo.addEventListener('input', () => {
    memoCount.textContent = workMemo.value.length;
  });

  issueContent.addEventListener('input', () => {
    issueCount.textContent = issueContent.value.length;
  });

  // 異常報告チェックボックスの制御
  const hasIssueCheckbox = container.querySelector('#has-issue');
  const issueSection = container.querySelector('#issue-content-section');

  hasIssueCheckbox.addEventListener('change', () => {
    if (hasIssueCheckbox.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      issueContent.value = '';
      issueCount.textContent = '0';
    }
  });

  // バリデーション関数
  function validateForm() {
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = hasIssueCheckbox.checked;
    const issueContentValue = issueContent.value.trim();
    const workMemoValue = workMemo.value.trim();

    // 完了状況必須チェック
    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssue && !issueContentValue) {
      showError('異常報告にチェックを入れた場合は、異常内容を入力してください。');
      return false;
    }

    // 文字数制限チェック
    if (workMemoValue.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueContentValue.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    if (!validateForm()) return;

    if (!currentWorkRecord) {
      showError('作業記録が見つかりません。');
      return;
    }

    try {
      const completionStatus = container.querySelector('#completion-status').value;
      const workMemoValue = workMemo.value.trim();
      const hasIssue = hasIssueCheckbox.checked;
      const issueContentValue = issueContent.value.trim();

      // 作業記録の更新
      const updateData = {
        作業終了時刻: new Date().toISOString(),
        進捗状況: completionStatus,
        備考: workMemoValue,
        承認状態: '未承認'
      };

      const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue && issueContentValue) {
          const anomalyLog = {
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentWorkRecord.作業記録ID,
            ユーザーID: currentWorkRecord.作業員ID,
            異常値種別: '作業員報告',
            検出項目: '異常・問題報告',
            検出値: issueContentValue,
            閾値: 'N/A',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          await window.aivicApi.save(4, anomalyLog);
        }

        alert('工数記録が正常に確定されました。');
        // 前画面に戻る（作業記録画面など）
        window.history.back();
      } else {
        showError('記録の保存に失敗しました。');
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の保存中にエラーが発生しました。');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.history.back();
  });

  // 記録確認ボタン
  container.querySelector('#btn-check-record').addEventListener('click', () => {
    window.showScreen("scr-1778907226171");
  });

  // ホバー効果
  const buttons = container.querySelectorAll('button');
  buttons.forEach(btn => {
    if (btn.id === 'btn-confirm') {
      btn.addEventListener('mouseenter', () => {
        btn.style.background = 'var(--primary-hover)';
      });
      btn.addEventListener('mouseleave', () => {
        btn.style.background = 'var(--primary)';
      });
    } else {
      btn.addEventListener('mouseenter', () => {
        btn.style.background = 'rgba(255,255,255,0.05)';
      });
      btn.addEventListener('mouseleave', () => {
        btn.style.background = 'transparent';
      });
    }
  });

  // 初期データの読み込み
  initializeData();
}

function(container, apiUrl, tables) {
  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'workRecordLocalData';
  const SETTINGS_KEY = 'autoSaveSettings';

  // 設定のデフォルト値
  let settings = {
    saveInterval: 30,
    maxSaveCount: 100,
    autoSaveEnabled: true
  };

  // 自動保存タイマー
  let autoSaveTimer = null;

  // ローカルデータを取得
  function getLocalData() {
    try {
      const data = localStorage.getItem(LOCAL_STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('ローカルデータの取得に失敗:', e);
      return [];
    }
  }

  // ローカルデータを保存
  function saveLocalData(data) {
    try {
      // 最大件数を超える場合は古いデータを削除
      if (data.length > settings.maxSaveCount) {
        data = data.slice(-settings.maxSaveCount);
      }
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
      return true;
    } catch (e) {
      console.error('ローカルデータの保存に失敗:', e);
      showError('ストレージ容量不足のため保存に失敗しました。不要なデータを削除してください。');
      return false;
    }
  }

  // 設定を読み込み
  function loadSettings() {
    try {
      const saved = localStorage.getItem(SETTINGS_KEY);
      if (saved) {
        settings = { ...settings, ...JSON.parse(saved) };
      }
    } catch (e) {
      console.error('設定の読み込みに失敗:', e);
    }

    // UIに反映
    container.querySelector('#save-interval').value = settings.saveInterval;
    container.querySelector('#max-save-count').value = settings.maxSaveCount;
  }

  // 設定を保存
  function saveSettings() {
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
      return true;
    } catch (e) {
      console.error('設定の保存に失敗:', e);
      return false;
    }
  }

  // ローカルデータテーブルを再描画
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    const localData = getLocalData();

    if (localData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">ローカル保存データはありません</td></tr>';
      return;
    }

    tbody.innerHTML = localData.map(item => `
      <tr data-id="${item.id}">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(item.作業日).toLocaleString()}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${item.作業内容 || '--'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34, 197, 94, 0.2); color: #22c562;' : 'background: rgba(251, 191, 36, 0.2); color: #fbbf24;'}">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(item.savedAt).toLocaleString()}</td>
        <td style="padding: 6px 10px;">
          ${!item.synced ? `<button class="action-btn secondary sync-btn" data-id="${item.id}" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">同期</button>` : ''}
          <button class="action-btn secondary delete-btn" data-id="${item.id}" style="padding: 4px 8px; font-size: 11px;">削除</button>
        </td>
      </tr>
    `).join('');

    // 同期待ち件数を更新
    const pendingCount = localData.filter(item => !item.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;
  }

  // ステータス表示を更新
  function updateStatus() {
    const statusEl = container.querySelector('#auto-save-status');
    const networkEl = container.querySelector('#network-status');
    const lastSaveEl = container.querySelector('#last-save-time');

    statusEl.textContent = settings.autoSaveEnabled ? '有効' : '無効';
    networkEl.textContent = navigator.onLine ? 'オンライン' : 'オフライン';

    const localData = getLocalData();
    if (localData.length > 0) {
      const lastSave = Math.max(...localData.map(item => new Date(item.savedAt).getTime()));
      lastSaveEl.textContent = new Date(lastSave).toLocaleTimeString();
    }
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-notification').style.display = 'none';
  }

  // 自動保存を開始
  function startAutoSave() {
    if (autoSaveTimer) {
      clearInterval(autoSaveTimer);
    }

    if (settings.autoSaveEnabled && settings.saveInterval > 0) {
      autoSaveTimer = setInterval(() => {
        // 実際のアプリでは現在編集中のデータを自動保存
        // ここではデモ用の処理
        console.log('自動保存実行');
      }, settings.saveInterval * 1000);
    }
  }

  // 手動同期実行
  async function performManualSync() {
    const progressEl = container.querySelector('#sync-progress');
    progressEl.style.display = 'block';

    try {
      const localData = getLocalData();
      const unsyncedData = localData.filter(item => !item.synced);

      if (unsyncedData.length === 0) {
        alert('同期待ちのデータはありません');
        return;
      }

      // 各未同期データを順次同期
      for (const item of unsyncedData) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: item.作業員ID,
            作業日: item.作業日,
            作業開始時刻: item.作業開始時刻,
            作業終了時刻: item.作業終了時刻,
            プロジェクト名: item.プロジェクト名,
            作業場所: item.作業場所,
            作業種別: item.作業種別,
            作業内容: item.作業内容,
            進捗状況: item.進捗状況,
            承認状態: '未承認',
            作成者ID: item.作業員ID
          });

          if (saved) {
            // 同期成功をマーク
            item.synced = true;
          }
        } catch (e) {
          console.error('同期エラー:', e);
          showError(`データ同期に失敗しました: ${e.message}`);
        }
      }

      // ローカルデータを更新
      saveLocalData(localData);
      renderLocalData();
      updateStatus();

      alert('同期が完了しました');

    } catch (e) {
      console.error('同期処理エラー:', e);
      showError('同期処理中にエラーが発生しました');
    } finally {
      progressEl.style.display = 'none';
    }
  }

  // データ復旧
  function performDataRecovery() {
    const localData = getLocalData();
    if (localData.length === 0) {
      alert('復旧可能なデータはありません');
      return;
    }

    if (confirm(`${localData.length}件のローカルデータが見つかりました。復旧しますか？`)) {
      // 実際のアプリでは編集フォームにデータを復元
      alert('データ復旧を実行しました');
    }
  }

  // CSVエクスポート
  function exportLocalDataToCsv() {
    const localData = getLocalData();
    if (localData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['作業日時', '作業内容', '同期状態', '保存時刻'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...localData.map(item => [
        `"${new Date(item.作業日).toLocaleString()}"`,
        `"${item.作業内容 || ''}"`,
        `"${item.synced ? '同期済み' : '未同期'}"`,
        `"${new Date(item.savedAt).toLocaleString()}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `local_data_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadSettings();
  renderLocalData();
  updateStatus();
  startAutoSave();

  // ネットワーク状態の監視
  window.addEventListener('online', updateStatus);
  window.addEventListener('offline', updateStatus);

  // イベントリスナー
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  });

  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const intervalInput = container.querySelector('#save-interval');
    const maxCountInput = container.querySelector('#max-save-count');

    const interval = parseInt(intervalInput.value);
    const maxCount = parseInt(maxCountInput.value);

    if (interval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      return;
    }

    if (maxCount < 10) {
      showError('最大保存件数は10件以上で設定してください');
      return;
    }

    settings.saveInterval = interval;
    settings.maxSaveCount = maxCount;

    if (saveSettings()) {
      alert('設定を保存しました');
      startAutoSave(); // タイマーを再開
    } else {
      showError('設定の保存に失敗しました');
    }
  });

  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);
  container.querySelector('#btn-data-recovery').addEventListener('click', performDataRecovery);
  container.querySelector('#btn-dismiss-error').addEventListener('click', hideError);

  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカル保存データをすべて削除しますか？')) {
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      renderLocalData();
      updateStatus();
      alert('ローカルデータを削除しました');
    }
  });

  container.querySelector('#btn-export-local').addEventListener('click', exportLocalDataToCsv);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const syncBtn = e.target.closest('.sync-btn');

    if (deleteBtn) {
      if (!confirm('このデータを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      const localData = getLocalData();
      const filteredData = localData.filter(item => item.id !== id);

      if (saveLocalData(filteredData)) {
        renderLocalData();
        updateStatus();
      }
    }

    if (syncBtn) {
      const id = syncBtn.dataset.id;
      const localData = getLocalData();
      const item = localData.find(item => item.id === id);

      if (item) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: item.作業員ID,
            作業日: item.作業日,
            作業開始時刻: item.作業開始時刻,
            作業終了時刻: item.作業終了時刻,
            プロジェクト名: item.プロジェクト名,
            作業場所: item.作業場所,
            作業種別: item.作業種別,
            作業内容: item.作業内容,
            進捗状況: item.進捗状況,
            承認状態: '未承認',
            作成者ID: item.作業員ID
          });

          if (saved) {
            item.synced = true;
            saveLocalData(localData);
            renderLocalData();
            updateStatus();
            alert('同期が完了しました');
          }
        } catch (e) {
          showError('同期に失敗しました');
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let recordedAudioBlob = null;
  let currentAudio = null;

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#input-work-item');
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID || item.id;
        option.textContent = `${item.作業項目コード || ''} ${item.作業項目名 || ''}`.trim();
        select.appendChild(option);
      });
    }
  }

  // 中断時間の自動計算
  function calculateDuration() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const display = container.querySelector('#duration-display');

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        display.textContent = `${hours}時間${minutes}分`;
      } else {
        display.textContent = '無効な時間範囲';
      }
    } else {
      display.textContent = '自動計算されます';
    }
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#input-details');
    const counter = container.querySelector('#char-count');
    counter.textContent = textarea.value.length;
  }

  // 影響範囲の全選択・全解除
  function setupImpactSelection() {
    const selectAll = container.querySelector('#select-all-impact');
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]');

    selectAll.addEventListener('change', () => {
      impactCheckboxes.forEach(cb => cb.checked = selectAll.checked);
    });

    impactCheckboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        const allChecked = Array.from(impactCheckboxes).every(c => c.checked);
        const noneChecked = Array.from(impactCheckboxes).every(c => !c.checked);
        selectAll.checked = allChecked;
        selectAll.indeterminate = !allChecked && !noneChecked;
      });
    });
  }

  // 写真添付
  function setupPhotoUpload() {
    const fileInput = container.querySelector('#input-photo');
    const photoBtn = container.querySelector('#btn-photo');
    const preview = container.querySelector('#photo-preview');
    const previewImg = container.querySelector('#preview-image');
    const removeBtn = container.querySelector('#btn-remove-photo');

    photoBtn.addEventListener('click', () => fileInput.click());

    fileInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('対応外のファイル形式です。画像ファイルを選択してください。');
        return;
      }

      // ファイルサイズチェック（10MB）
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズが上限（10MB）を超えています。');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        previewImg.src = e.target.result;
        preview.style.display = 'block';
      };
      reader.readAsDataURL(file);
    });

    removeBtn.addEventListener('click', () => {
      fileInput.value = '';
      preview.style.display = 'none';
      previewImg.src = '';
    });
  }

  // 音声録音
  function setupAudioRecording() {
    const recordBtn = container.querySelector('#btn-record');
    const stopBtn = container.querySelector('#btn-stop-record');
    const playBtn = container.querySelector('#btn-play');
    const status = container.querySelector('#recording-status');

    recordBtn.addEventListener('click', async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (e) => audioChunks.push(e.data);
        mediaRecorder.onstop = () => {
          recordedAudioBlob = new Blob(audioChunks, { type: 'audio/wav' });
          playBtn.style.display = 'inline-block';
          status.textContent = '録音完了';
        };

        mediaRecorder.start();
        recordBtn.style.display = 'none';
        stopBtn.style.display = 'inline-block';
        status.textContent = '録音中...';
      } catch (error) {
        showError('録音に失敗しました。マイクへのアクセスを許可してください。');
      }
    });

    stopBtn.addEventListener('click', () => {
      if (mediaRecorder && mediaRecorder.state === 'recording') {
        mediaRecorder.stop();
        mediaRecorder.stream.getTracks().forEach(track => track.stop());
        recordBtn.style.display = 'inline-block';
        stopBtn.style.display = 'none';
      }
    });

    playBtn.addEventListener('click', () => {
      if (recordedAudioBlob) {
        if (currentAudio) currentAudio.pause();
        currentAudio = new Audio(URL.createObjectURL(recordedAudioBlob));
        currentAudio.play();
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => errorDiv.style.display = 'none', 5000);
  }

  // 成功表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.style.display = 'block';
    setTimeout(() => successDiv.style.display = 'none', 3000);
  }

  // バリデーション
  function validateForm() {
    const startTime = container.querySelector('#input-start-time').value;
    const reason = container.querySelector('#input-reason').value;
    const details = container.querySelector('#input-details').value;

    if (!startTime) {
      showError('中断開始時刻は必須です。');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です。');
      return false;
    }

    // 未来時刻チェック
    const now = new Date();
    const start = new Date(startTime);
    if (start > now) {
      showError('未来の時刻は入力できません。');
      return false;
    }

    // 文字数チェック
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const reason = container.querySelector('#input-reason').value;
    const location = container.querySelector('#input-location').value;
    const workItem = container.querySelector('#input-work-item').value;
    const details = container.querySelector('#input-details').value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || '中';
    const impacts = Array.from(container.querySelectorAll('input[name="impact"]:checked')).map(cb => cb.value);

    // 中断時間計算
    let duration = null;
    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;
      if (diffMs > 0) {
        duration = Math.floor(diffMs / (1000 * 60)); // 分単位
      }
    }

    return {
      作業記録ID: workItem || null,
      中断開始日時: startTime ? new Date(startTime).toISOString() : null,
      中断終了日時: endTime ? new Date(endTime).toISOString() : null,
      中断理由区分: reason,
      中断理由詳細: details,
      中断時間: duration,
      影響度: urgency,
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証情報から取得
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  async function tempSave() {
    const formData = collectFormData();
    localStorage.setItem('temp_interruption_record', JSON.stringify(formData));
    showSuccess('一時保存しました。');
  }

  // 一時保存データの復元
  function restoreTempData() {
    const tempData = localStorage.getItem('temp_interruption_record');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) {
          container.querySelector('#input-start-time').value = new Date(data.中断開始日時).toISOString().slice(0, 16);
        }
        if (data.中断終了日時) {
          container.querySelector('#input-end-time').value = new Date(data.中断終了日時).toISOString().slice(0, 16);
        }
        if (data.中断理由区分) {
          container.querySelector('#input-reason').value = data.中断理由区分;
        }
        if (data.中断理由詳細) {
          container.querySelector('#input-details').value = data.中断理由詳細;
        }
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        calculateDuration();
        updateCharCount();
      } catch (error) {
        console.error('一時保存データの復元に失敗:', error);
      }
    }
  }

  // 記録完了
  async function completeRecord() {
    if (!validateForm()) return;

    try {
      const formData = collectFormData();
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル

      if (saved) {
        localStorage.removeItem('temp_interruption_record');
        showSuccess('中断記録を保存しました。');
        setTimeout(() => {
          window.showScreen("scr-1778907251446"); // 作業再開記録画面
        }, 1500);
      } else {
        showError('ネットワークに接続できません。後でもう一度お試しください。');
      }
    } catch (error) {
      showError('記録の保存に失敗しました。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#input-start-time').addEventListener('change', calculateDuration);
  container.querySelector('#input-end-time').addEventListener('change', calculateDuration);
  container.querySelector('#input-details').addEventListener('input', updateCharCount);
  container.querySelector('#btn-temp-save').addEventListener('click', tempSave);
  container.querySelector('#btn-complete').addEventListener('click', completeRecord);

  // 初期化
  loadWorkItems();
  setupImpactSelection();
  setupPhotoUpload();
  setupAudioRecording();
  restoreTempData();

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  now.setSeconds(0, 0); // 秒とミリ秒を0にセット
  container.querySelector('#input-start-time').value = now.toISOString().slice(0, 16);
  calculateDuration();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks(workRecords, interruptRecords) {
    const tbody = container.querySelector("#suspended-works-tbody");
    const noWorksMsg = container.querySelector("#no-suspended-works");
    const table = container.querySelector("#suspended-works-table");

    // 中断中の作業記録を抽出（進捗状況が「中断」のもの）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

    if (suspendedWorks.length === 0) {
      table.style.display = 'none';
      noWorksMsg.classList.remove('hidden');
      return;
    }

    table.style.display = 'table';
    noWorksMsg.classList.add('hidden');

    tbody.innerHTML = suspendedWorks.map(work => {
      // この作業に関連する最新の中断記録を取得
      const relatedInterrupts = interruptRecords.filter(interrupt => 
        interrupt.作業記録ID === work.作業記録ID && !interrupt.中断終了日時
      );
      const latestInterrupt = relatedInterrupts.length > 0 ? relatedInterrupts[relatedInterrupts.length - 1] : null;

      const suspendTime = latestInterrupt ? 
        new Date(latestInterrupt.中断開始日時).toLocaleString('ja-JP') : '-';
      const suspendReason = latestInterrupt ? (latestInterrupt.中断理由詳細 || latestInterrupt.中断理由区分) : '-';

      return `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${latestInterrupt?.中断記録ID || ''}" style="cursor: pointer;">
          <td><input type="radio" name="selected-work" value="${work.作業記録ID}" style="accent-color: var(--primary);"></td>
          <td>${work.作業内容 || '-'}</td>
          <td>${work.プロジェクト名 || '-'}</td>
          <td>${suspendTime}</td>
          <td>${suspendReason}</td>
          <td>${work.作業場所 || '-'}</td>
        </tr>
      `;
    }).join('');

    // 行クリックで選択
    tbody.addEventListener('click', (e) => {
      const row = e.target.closest('tr');
      if (row) {
        const radio = row.querySelector('input[type="radio"]');
        radio.checked = true;
        selectWork(row);
      }
    });

    // ラジオボタン変更で選択
    tbody.addEventListener('change', (e) => {
      if (e.target.type === 'radio') {
        const row = e.target.closest('tr');
        selectWork(row);
      }
    });
  }

  // 作業選択処理
  function selectWork(row) {
    const workId = row.dataset.workId;
    const interruptId = row.dataset.interruptId;

    // 選択された作業記録と中断記録を保存
    selectedWorkRecord = (tables[1].records || []).find(w => w.作業記録ID === workId);
    selectedInterruptRecord = interruptId ? (tables[2].records || []).find(i => i.中断記録ID === interruptId) : null;

    if (selectedWorkRecord) {
      // 選択された作業の詳細を表示
      container.querySelector("#selected-work-name").textContent = selectedWorkRecord.作業内容 || '-';
      container.querySelector("#selected-project-name").textContent = selectedWorkRecord.プロジェクト名 || '-';

      const suspendTime = selectedInterruptRecord ? 
        new Date(selectedInterruptRecord.中断開始日時).toLocaleString('ja-JP') : '-';
      container.querySelector("#selected-suspend-time").textContent = suspendTime;

      const suspendReason = selectedInterruptRecord ? 
        (selectedInterruptRecord.中断理由詳細 || selectedInterruptRecord.中断理由区分) : '-';
      container.querySelector("#selected-suspend-reason").textContent = suspendReason;

      // フォームを表示
      container.querySelector("#resume-form").classList.remove('hidden');
      setCurrentTime();
    }
  }

  // 文字数カウント
  const reasonDetail = container.querySelector("#resume-reason-detail");
  const charCount = container.querySelector("#char-count");

  reasonDetail.addEventListener('input', () => {
    charCount.textContent = reasonDetail.value.length;
  });

  // 再開理由選択時の処理
  container.querySelector("#resume-reason-select").addEventListener('change', (e) => {
    const detailField = container.querySelector("#resume-reason-detail");
    if (e.target.value && e.target.value !== 'その他') {
      detailField.value = e.target.value;
      charCount.textContent = detailField.value.length;
    }
  });

  // バリデーション
  function validateResumeForm() {
    const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();
    const errorDiv = container.querySelector("#resume-reason-error");

    errorDiv.classList.add('hidden');

    if (!reasonDetail) {
      errorDiv.textContent = '再開理由は必須です';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (reasonDetail.length > 500) {
      errorDiv.textContent = '再開理由は500文字以内で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    return true;
  }

  // 作業再開確認ボタン
  container.querySelector("#btn-confirm-resume").addEventListener('click', () => {
    if (!selectedWorkRecord) {
      alert('作業を選択してください');
      return;
    }

    if (!validateResumeForm()) {
      return;
    }

    // 確認ダイアログを表示
    container.querySelector("#resume-confirm-dialog").classList.remove('hidden');
  });

  // ダイアログのOKボタン
  container.querySelector("#btn-dialog-ok").addEventListener('click', async () => {
    container.querySelector("#resume-confirm-dialog").classList.add('hidden');

    try {
      const resumeTime = container.querySelector("#resume-time").value;
      const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();

      // 作業記録を「作業中」に更新
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        更新日時: new Date().toISOString()
      });

      if (updatedWork) {
        // 中断記録に終了時刻を設定
        if (selectedInterruptRecord) {
          await window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
            中断終了日時: new Date(resumeTime).toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        alert('作業を再開しました');

        // 工数入力画面に遷移
        window.showScreen("scr-1778907296658");
      } else {
        alert('作業再開の記録に失敗しました');
      }
    } catch (error) {
      console.error('作業再開エラー:', error);
      alert('作業再開の記録に失敗しました');
    }
  });

  // ダイアログのキャンセルボタン
  container.querySelector("#btn-dialog-cancel").addEventListener('click', () => {
    container.querySelector("#resume-confirm-dialog").classList.remove('hidden');
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel-resume").addEventListener('click', () => {
    container.querySelector("#resume-form").classList.add('hidden');
    selectedWorkRecord = null;
    selectedInterruptRecord = null;

    // ラジオボタンの選択を解除
    const radios = container.querySelectorAll('input[name="selected-work"]');
    radios.forEach(radio => radio.checked = false);
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener('click', () => {
    history.back();
  });

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const workRecords = await window.aivicApi.list(1) || tables[1].records || [];
      const interruptRecords = await window.aivicApi.list(2) || tables[2].records || [];

      renderSuspendedWorks(workRecords, interruptRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // フォールバック: 初期データを使用
      renderSuspendedWorks(tables[1].records || [], tables[2].records || []);
    }
  }

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // エラー情報の管理
  let currentError = {
    title: 'システムエラーが発生しました',
    message: 'データの保存に失敗しました。ネットワーク接続を確認してください。',
    code: 'E001',
    timestamp: new Date().toLocaleString('ja-JP', { 
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    }),
    solution: 'ネットワーク接続を確認し、再試行ボタンをクリックしてください。問題が続く場合は管理者にお問い合わせください。',
    details: 'Network Error: Failed to fetch data from server. Status: 500, Response: Internal Server Error',
    isNetworkError: true,
    retryCount: 0
  };

  // 前の画面情報を保持
  let previousScreen = 'scr-1778907133295'; // 工数記録画面をデフォルトとする
  let retryAction = null;

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-title').textContent = currentError.title;
    container.querySelector('#error-message').textContent = currentError.message;
    container.querySelector('#error-code').textContent = currentError.code;
    container.querySelector('#error-timestamp').textContent = currentError.timestamp;
    container.querySelector('#error-solution').textContent = currentError.solution;
    container.querySelector('#error-details-content').textContent = currentError.details;

    // ネットワークエラー通知の表示制御
    const networkNotice = container.querySelector('#network-error-notice');
    if (currentError.isNetworkError) {
      networkNotice.classList.remove('hidden');
    } else {
      networkNotice.classList.add('hidden');
    }
  }

  // エラー詳細表示ボタン
  container.querySelector('#btn-show-details').addEventListener('click', () => {
    const detailsDiv = container.querySelector('#error-details');
    const btn = container.querySelector('#btn-show-details');

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      btn.textContent = 'エラー詳細を非表示';
    } else {
      detailsDiv.classList.add('hidden');
      btn.textContent = 'エラー詳細を表示';
    }
  });

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    const btn = container.querySelector('#btn-retry');
    const originalText = btn.textContent;

    // ボタンを無効化
    btn.disabled = true;
    btn.textContent = '再試行中...';
    btn.style.background = 'rgba(var(--primary), 0.5)';

    try {
      currentError.retryCount++;

      // ネットワーク接続チェック（簡易）
      if (currentError.isNetworkError && !navigator.onLine) {
        throw new Error('ネットワークに接続されていません');
      }

      // retryAction が設定されている場合は実行
      if (retryAction && typeof retryAction === 'function') {
        await retryAction();
      }

      // 成功時は前の画面に戻る
      window.showScreen(previousScreen);

    } catch (error) {
      // 再試行失敗
      currentError.message = `再試行に失敗しました (${currentError.retryCount}回目)。${error.message}`;
      currentError.timestamp = new Date().toLocaleString('ja-JP', { 
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
      });
      updateErrorDisplay();
    } finally {
      // ボタンを有効化
      btn.disabled = false;
      btn.textContent = originalText;
      btn.style.background = 'var(--primary)';
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    // セッション切れチェック
    const token = localStorage.getItem('authToken');
    if (!token) {
      window.location.href = './login.html';
      return;
    }

    window.showScreen(previousScreen);
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（メイン画面）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact-admin').addEventListener('click', async () => {
    const btn = container.querySelector('#btn-contact-admin');
    const originalText = btn.textContent;

    btn.disabled = true;
    btn.textContent = '連絡中...';

    try {
      // 管理者連絡機能の呼び出し（模擬）
      if (!navigator.onLine) {
        throw new Error('オフライン状態では管理者連絡機能を利用できません');
      }

      // 緊急報告画面に遷移
      window.showScreen('scr-1778907330826');

    } catch (error) {
      // 管理者連絡機能エラー時の代替連絡先表示
      const fallbackDiv = container.querySelector('#contact-fallback');
      fallbackDiv.classList.remove('hidden');

      btn.textContent = originalText;
      btn.disabled = false;
    }
  });

  // URLパラメータからエラー情報を取得（他画面からの遷移時）
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      currentError = { ...currentError, ...errorData };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  if (urlParams.get('previousScreen')) {
    previousScreen = urlParams.get('previousScreen');
  }

  // 外部からエラー情報を設定するためのグローバル関数
  window.showErrorScreen = (errorInfo, prevScreen, retryFn) => {
    if (errorInfo) {
      currentError = { ...currentError, ...errorInfo };
    }
    if (prevScreen) {
      previousScreen = prevScreen;
    }
    if (retryFn) {
      retryAction = retryFn;
    }
    updateErrorDisplay();
  };

  // 長いエラーメッセージの制限処理
  function limitErrorMessage() {
    const messageDiv = container.querySelector('#error-message');
    const maxLength = 500;

    if (currentError.message.length > maxLength) {
      const truncated = currentError.message.substring(0, maxLength) + '...';
      messageDiv.textContent = truncated;
      messageDiv.title = currentError.message; // ツールチップで全文表示
    }
  }

  // 初期表示
  updateErrorDisplay();
  limitErrorMessage();

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    if (currentError.isNetworkError) {
      const networkNotice = container.querySelector('#network-error-notice');
      networkNotice.style.background = 'rgba(34, 197, 94, 0.1)';
      networkNotice.style.borderColor = 'rgba(34, 197, 94, 0.3)';
      networkNotice.innerHTML = '<div style="font-size: 12px; color: var(--text);"><strong>ネットワーク復旧:</strong> インターネット接続が復旧しました。再試行をお試しください。</div>';
    }
  });

  window.addEventListener('offline', () => {
    const networkNotice = container.querySelector('#network-error-notice');
    networkNotice.classList.remove('hidden');
    networkNotice.style.background = 'rgba(255, 71, 87, 0.1)';
    networkNotice.style.borderColor = 'rgba(255, 71, 87, 0.3)';
    networkNotice.innerHTML = '<div style="font-size: 12px; color: var(--text);"><strong>ネットワーク切断:</strong> インターネット接続が切断されました。</div>';
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecordId = null;
  let interruptions = [];

  // DOM要素の取得
  const workDateInput = container.querySelector('#work-date');
  const workItemSelect = container.querySelector('#work-item');
  const workLocationInput = container.querySelector('#work-location');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const breakTimeInput = container.querySelector('#break-time');
  const actualWorkTimeInput = container.querySelector('#actual-work-time');
  const workerNameInput = container.querySelector('#worker-name');
  const workDetailsTextarea = container.querySelector('#work-details');
  const charCountSpan = container.querySelector('#char-count');
  const errorMessageDiv = container.querySelector('#error-message');
  const interruptionForm = container.querySelector('#interruption-form');
  const interruptionList = container.querySelector('#interruption-list');

  // 初期化
  function init() {
    // 現在日付を設定
    const today = new Date().toISOString().split('T')[0];
    workDateInput.value = today;

    // 担当者名を設定（ログインユーザー情報から取得）
    workerNameInput.value = 'ログインユーザー'; // 実際の実装では認証情報から取得

    // 作業項目の読み込み
    loadWorkItems();

    // イベントリスナーの設定
    setupEventListeners();
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      if (workItems) {
        workItemSelect.innerHTML = '<option value="">選択してください</option>';
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.id;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 実働時間の自動計算
    startTimeInput.addEventListener('change', calculateWorkTime);
    endTimeInput.addEventListener('change', calculateWorkTime);
    breakTimeInput.addEventListener('input', calculateWorkTime);

    // 文字数カウント
    workDetailsTextarea.addEventListener('input', updateCharCount);

    // 登録ボタン
    container.querySelector('#btn-register').addEventListener('click', registerWorkRecord);

    // 中断記録関連
    container.querySelector('#btn-add-interruption').addEventListener('click', showInterruptionForm);
    container.querySelector('#btn-cancel-interruption').addEventListener('click', hideInterruptionForm);
    container.querySelector('#btn-save-interruption').addEventListener('click', saveInterruption);

    // 画面遷移ボタン
    container.querySelector('#btn-interrupt').addEventListener('click', () => {
      window.showScreen("scr-1778907238439");
    });
    container.querySelector('#btn-complete').addEventListener('click', () => {
      window.showScreen("scr-1778907199709");
    });

    // 中断記録の削除
    container.addEventListener('click', (e) => {
      if (e.target.classList.contains('delete-interruption-btn')) {
        const index = parseInt(e.target.dataset.index);
        interruptions.splice(index, 1);
        renderInterruptions();
      }
    });
  }

  // 実働時間の計算
  function calculateWorkTime() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const breakMinutes = parseInt(breakTimeInput.value) || 0;

    if (!startTime || !endTime) {
      actualWorkTimeInput.value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 24時間をまたぐ場合の処理
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const totalMinutes = Math.floor(diffMs / (1000 * 60));
    const workMinutes = totalMinutes - breakMinutes;

    if (workMinutes < 0) {
      actualWorkTimeInput.value = '';
      return;
    }

    const hours = Math.floor(workMinutes / 60);
    const minutes = workMinutes % 60;
    actualWorkTimeInput.value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 文字数カウント更新
  function updateCharCount() {
    const count = workDetailsTextarea.value.length;
    charCountSpan.textContent = count;

    if (count > 500) {
      charCountSpan.style.color = '#fca5a5';
    } else {
      charCountSpan.style.color = 'var(--text-muted)';
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessageDiv.textContent = message;
    errorMessageDiv.style.display = 'block';
    setTimeout(() => {
      errorMessageDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workDate = workDateInput.value;
    const workItem = workItemSelect.value;
    const workLocation = workLocationInput.value.trim();
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const workDetails = workDetailsTextarea.value.trim();

    // 必須項目チェック
    if (!workDate) {
      showError('作業日付を入力してください。');
      return false;
    }

    if (!workItem) {
      showError('作業項目を選択してください。');
      return false;
    }

    if (!workLocation) {
      showError('作業場所を入力してください。');
      return false;
    }

    if (!startTime) {
      showError('開始時刻を入力してください。');
      return false;
    }

    if (!endTime) {
      showError('終了時刻を入力してください。');
      return false;
    }

    if (!workDetails) {
      showError('作業内容詳細を入力してください。');
      return false;
    }

    // 未来日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (workDate > today) {
      showError('未来の日付は選択できません。');
      return false;
    }

    // 時刻フォーマットチェック
    const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime)) {
      showError('開始時刻の形式が正しくありません。');
      return false;
    }

    if (!timeRegex.test(endTime)) {
      showError('終了時刻の形式が正しくありません。');
      return false;
    }

    // 開始終了時刻の関係チェック
    if (startTime === endTime) {
      showError('開始時刻と終了時刻が同じです。');
      return false;
    }

    // 実働時間チェック
    const breakMinutes = parseInt(breakTimeInput.value) || 0;
    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = Math.floor((end - start) / (1000 * 60));

    if (breakMinutes > totalMinutes) {
      showError('休憩時間が実働時間を超過しています。');
      return false;
    }

    if (breakMinutes < 0) {
      showError('休憩時間は0分以上で入力してください。');
      return false;
    }

    // 文字数チェック
    if (workDetails.length > 500) {
      showError('作業内容詳細は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 工数記録の登録
  async function registerWorkRecord() {
    if (!validateForm()) {
      return;
    }

    try {
      const workData = {
        作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
        作業日: new Date(workDateInput.value).toISOString(),
        作業開始時刻: new Date(`${workDateInput.value}T${startTimeInput.value}`).toISOString(),
        作業終了時刻: new Date(`${workDateInput.value}T${endTimeInput.value}`).toISOString(),
        作業時間: calculateTotalMinutes(),
        プロジェクト名: workItemSelect.options[workItemSelect.selectedIndex].text,
        作業場所: workLocationInput.value.trim(),
        作業種別: '一般作業',
        作業内容: workDetailsTextarea.value.trim(),
        進捗状況: '完了',
        備考: '',
        承認状態: '未承認',
        作成者ID: 'current-user-id'
      };

      const savedRecord = await window.aivicApi.save(1, workData); // 作業記録テーブル

      if (savedRecord) {
        currentWorkRecordId = savedRecord.id;

        // 中断記録も保存
        for (const interruption of interruptions) {
          await window.aivicApi.save(2, {
            作業記録ID: currentWorkRecordId,
            中断開始日時: new Date(`${workDateInput.value}T${interruption.startTime}`).toISOString(),
            中断終了日時: new Date(`${workDateInput.value}T${interruption.endTime}`).toISOString(),
            中断理由区分: interruption.reason,
            中断理由詳細: interruption.details,
            中断時間: interruption.duration,
            影響度: '軽微',
            対応状況: '解決済み',
            記録者ID: 'current-user-id'
          });
        }

        alert('工数記録が正常に登録されました。');
        resetForm();
      }
    } catch (error) {
      console.error('工数記録の登録に失敗しました:', error);
      showError('工数記録の登録に失敗しました。');
    }
  }

  // 総作業時間の計算（分）
  function calculateTotalMinutes() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const breakMinutes = parseInt(breakTimeInput.value) || 0;

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = Math.floor((end - start) / (1000 * 60));
    return totalMinutes - breakMinutes;
  }

  // フォームのリセット
  function resetForm() {
    const today = new Date().toISOString().split('T')[0];
    workDateInput.value = today;
    workItemSelect.value = '';
    workLocationInput.value = '';
    startTimeInput.value = '';
    endTimeInput.value = '';
    breakTimeInput.value = '';
    actualWorkTimeInput.value = '';
    workDetailsTextarea.value = '';
    charCountSpan.textContent = '0';
    interruptions = [];
    renderInterruptions();
    hideInterruptionForm();
  }

  // 中断記録フォームの表示
  function showInterruptionForm() {
    interruptionForm.style.display = 'block';
  }

  // 中断記録フォームの非表示
  function hideInterruptionForm() {
    interruptionForm.style.display = 'none';
    // フォームをクリア
    container.querySelector('#interruption-reason').value = '';
    container.querySelector('#interruption-start').value = '';
    container.querySelector('#interruption-end').value = '';
    container.querySelector('#interruption-details').value = '';
  }

  // 中断記録の保存
  function saveInterruption() {
    const reason = container.querySelector('#interruption-reason').value;
    const startTime = container.querySelector('#interruption-start').value;
    const endTime = container.querySelector('#interruption-end').value;
    const details = container.querySelector('#interruption-details').value;

    if (!reason || !startTime || !endTime) {
      showError('中断記録の必須項目を入力してください。');
      return;
    }

    if (startTime >= endTime) {
      showError('中断開始時刻は終了時刻より前に設定してください。');
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    const duration = Math.floor((end - start) / (1000 * 60));

    const interruption = {
      reason,
      startTime,
      endTime,
      duration,
      details
    };

    interruptions.push(interruption);
    renderInterruptions();
    hideInterruptionForm();
  }

  // 中断記録の描画
  function renderInterruptions() {
    interruptionList.innerHTML = interruptions.map((interruption, index) => `
      <tr>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${interruption.reason}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${interruption.startTime}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${interruption.endTime}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${interruption.duration}分</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary delete-interruption-btn" data-index="${index}" style="font-size: 11px; padding: 2px 6px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let breakRecords = [];
  let selectedRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || []; // 作業記録
      workItems = await window.aivicApi.list(3) || []; // 作業項目マスタ
      breakRecords = await window.aivicApi.list(2) || []; // 中断記録

      renderTargetRecords();
      renderWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のドロップダウンを描画
  function renderTargetRecords() {
    const select = container.querySelector('#select-target-record');
    select.innerHTML = '<option value="">記録を選択してください</option>';

    workRecords.forEach(record => {
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      const option = document.createElement('option');
      option.value = record.作業記録ID;
      option.textContent = `${workDate} - ${record.プロジェクト名} (${record.作業種別})`;
      select.appendChild(option);
    });
  }

  // 作業項目のドロップダウンを描画
  function renderWorkItems() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">作業項目を選択</option>';

    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
  }

  // 修正対象記録選択時の処理
  container.querySelector('#select-target-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      container.querySelector('#correction-form').style.display = 'none';
      selectedRecord = null;
      return;
    }

    selectedRecord = workRecords.find(r => r.作業記録ID === recordId);
    if (selectedRecord) {
      populateForm(selectedRecord);
      container.querySelector('#correction-form').style.display = 'block';
    }
  });

  // フォームに既存データを設定
  function populateForm(record) {
    const workDate = new Date(record.作業日);
    container.querySelector('#input-work-date').value = workDate.toISOString().split('T')[0];

    if (record.作業開始時刻) {
      const startTime = new Date(record.作業開始時刻);
      container.querySelector('#input-start-time').value = startTime.toTimeString().slice(0, 5);
    }

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      container.querySelector('#input-end-time').value = endTime.toTimeString().slice(0, 5);
    }

    // 作業項目を設定（プロジェクト名から推測）
    const workItem = workItems.find(item => item.作業項目名.includes(record.作業種別));
    if (workItem) {
      container.querySelector('#select-work-item').value = workItem.作業項目ID;
    }

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID);
    if (breakRecord) {
      if (breakRecord.中断開始日時) {
        const breakTime = new Date(breakRecord.中断開始日時);
        container.querySelector('#input-break-time').value = breakTime.toTimeString().slice(0, 5);
      }
      container.querySelector('#select-break-reason').value = breakRecord.中断理由区分 || '';
    }

    // 修正前データを表示
    displayOriginalData(record, breakRecord);

    // 時間計算
    calculateTimes();
  }

  // 修正前データの表示
  function displayOriginalData(record, breakRecord) {
    const originalDataDiv = container.querySelector('#original-data');
    const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
    const startTime = record.作業開始時刻? new Date(record.作業開始時刻).toTimeString().slice(0, 5) : '-';
    const endTime = record.作業終了時刻? new Date(record.作業終了時刻).toTimeString().slice(0, 5) : '-';
    const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

    let breakInfo = '';
    if (breakRecord) {
      const breakTime = breakRecord.中断開始日時 ? new Date(breakRecord.中断開始日時).toTimeString().slice(0, 5) : '-';
      const breakDuration = breakRecord.中断時間 ? `${Math.floor(breakRecord.中断時間 / 60)}時間${breakRecord.中断時間 % 60}分` : '-';
      breakInfo = `<br>中断時刻: ${breakTime} | 中断理由: ${breakRecord.中断理由区分 || '-'} | 中断時間: ${breakDuration}`;
    }

    originalDataDiv.innerHTML = `
      作業日: ${workDate} | 開始: ${startTime} | 終了: ${endTime} | 作業時間: ${workTime}<br>
      プロジェクト: ${record.プロジェクト名} | 作業種別: ${record.作業種別}${breakInfo}
    `;
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = container.querySelector('#input-break-time').value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        let breakMinutes = 0;

        if (breakTime) {
          const breakDateTime = new Date(`2000-01-01T${breakTime}`);
          if (breakDateTime >= start && breakDateTime <= end) {
            // 簡易的に30分の中断時間を設定
            breakMinutes = 30;
          }
        }

        container.querySelector('#break-duration').textContent = breakMinutes > 0 ? `${Math.floor(breakMinutes / 60)}時間${breakMinutes % 60}分` : '-';

        const actualMinutes = totalMinutes - breakMinutes;
        container.querySelector('#actual-work-time').textContent = `${Math.floor(actualMinutes / 60)}時間${actualMinutes % 60}分`;

        // 異常値チェック
        checkAnomalies(actualMinutes, breakMinutes);
      }
    }
  }

  // 異常値チェック
  function checkAnomalies(workMinutes, breakMinutes) {
    const warnings = [];

    if (workMinutes > 12 * 60) { // 12時間超過
      warnings.push('作業時間が12時間を超えています');
    }

    if (workMinutes < 0) {
      warnings.push('作業時間が負の値になっています');
    }

    if (breakMinutes > workMinutes) {
      warnings.push('中断時間が作業時間を超えています');
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    if (startTime && endTime && startTime >= endTime) {
      warnings.push('開始時刻が終了時刻以降になっています');
    }

    const workDate = container.querySelector('#input-work-date').value;
    if (workDate && new Date(workDate) > new Date()) {
      warnings.push('未来の日付が設定されています');
    }

    const warningArea = container.querySelector('#warning-area');
    const warningMessages = container.querySelector('#warning-messages');

    if (warnings.length > 0) {
      warningMessages.innerHTML = warnings.map(w => `• ${w}`).join('<br>');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 修正理由の文字数カウント
  container.querySelector('#input-correction-reason').addEventListener('input', function() {
    const count = this.value.length;
    container.querySelector('#reason-char-count').textContent = count;
  });

  // 時刻変更時の再計算
  ['#input-start-time', '#input-end-time', '#input-break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!selectedRecord) {
      alert('修正対象の記録が選択されていません');
      return;
    }

    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    if (!correctionReason) {
      alert('修正理由を入力してください');
      return;
    }

    const warnings = container.querySelector('#warning-area').style.display !== 'none';
    if (warnings) {
      if (!confirm('異常値が検出されています。このまま保存しますか？')) {
        return;
      }
    }

    try {
      // 作業記録の更新
      const workDate = container.querySelector('#input-work-date').value;
      const startTime = container.querySelector('#input-start-time').value;
      const endTime = container.querySelector('#input-end-time').value;
      const workItemId = container.querySelector('#select-work-item').value;

      const startDateTime = new Date(`${workDate}T${startTime}`);
      const endDateTime = new Date(`${workDate}T${endTime}`);
      const workMinutes = (endDateTime - startDateTime) / (1000 * 60);

      const updatedRecord = {
        ...selectedRecord,
        作業日: new Date(workDate).toISOString(),
        作業開始時刻: startDateTime.toISOString(),
        作業終了時刻: endDateTime.toISOString(),
        作業時間: Math.max(0, workMinutes),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.update(1, selectedRecord.作業記録ID, updatedRecord);

      // 中断記録の更新
      const breakTime = container.querySelector('#input-break-time').value;
      const breakReason = container.querySelector('#select-break-reason').value;

      if (breakTime && breakReason) {
        const breakDateTime = new Date(`${workDate}T${breakTime}`);
        const existingBreak = breakRecords.find(br => br.作業記録ID === selectedRecord.作業記録ID);

        const breakData = {
          作業記録ID: selectedRecord.作業記録ID,
          中断開始日時: breakDateTime.toISOString(),
          中断理由区分: breakReason,
          中断時間: 30, // 簡易的に30分
          対応状況: '対応済み',
          記録者ID: selectedRecord.作業員ID,
          更新日時: new Date().toISOString()
        };

        if (existingBreak) {
          await window.aivicApi.update(2, existingBreak.中断記録ID, breakData);
        } else {
          breakData.中断記録ID = crypto.randomUUID();
          breakData.作成日時 = new Date().toISOString();
          await window.aivicApi.save(2, breakData);
        }
      }

      alert('修正が完了しました');

      // データを再読み込みしてフォームをリセット
      await loadData();
      container.querySelector('#select-target-record').value = '';
      container.querySelector('#correction-form').style.display = 'none';
      container.querySelector('#input-correction-reason').value = '';
      container.querySelector('#reason-char-count').textContent = '0';

    } catch (error) {
      console.error('保存エラー:', error);
      alert('修正の保存に失敗しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let uploadedFiles = [];
  let currentUser = null;

  // 現在のユーザー情報を取得（仮の実装）
  async function loadCurrentUser() {
    try {
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      currentUser = users.find(u => u.有効フラグ) || users[0];
      if (currentUser) {
        container.querySelector('#reporter-name').value = currentUser.氏名 || '';
      }
    } catch (error) {
      console.error('ユーザー情報の取得に失敗:', error);
    }
  }

  // 作業項目を読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const select = container.querySelector('#work-item');
      workItems.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = item.作業項目名;
        select.appendChild(option);
      });
    } catch (error) {
      console.error('作業項目の取得に失敗:', error);
    }
  }

  // 文字数カウンター
  const contentTextarea = container.querySelector('#emergency-content');
  const charCount = container.querySelector('#char-count');

  contentTextarea.addEventListener('input', function() {
    const length = this.value.length;
    charCount.textContent = `${length}/1000`;
    if (length > 1000) {
      charCount.style.color = '#ff4757';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  });

  // 写真アップロード処理
  const photoUploadArea = container.querySelector('#photo-upload-area');
  const photoInput = container.querySelector('#photo-input');
  const photoPreview = container.querySelector('#photo-preview');
  const photoError = container.querySelector('#photo-error');

  photoUploadArea.addEventListener('click', () => photoInput.click());

  photoUploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'var(--primary)';
  });

  photoUploadArea.addEventListener('dragleave', () => {
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  photoUploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFiles(e.dataTransfer.files);
  });

  photoInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    photoError.style.display = 'none';

    if (uploadedFiles.length + files.length > 5) {
      showError('photo-error', '画像は最大5枚まで添付できます');
      return;
    }

    Array.from(files).forEach(file => {
      if (!file.type.startsWith('image/')) {
        showError('photo-error', 'サポートされていないファイル形式です。JPG、PNG形式のファイルをアップロードしてください。');
        return;
      }

      if (file.size > 5 * 1024 * 1024) {
        showError('photo-error', 'ファイルサイズが上限を超えています。5MB以下のファイルを選択してください。');
        return;
      }

      uploadedFiles.push(file);

      const reader = new FileReader();
      reader.onload = (e) => {
        const preview = document.createElement('div');
        preview.style.cssText = 'position: relative; width: 80px; height: 80px; border-radius: 6px; overflow: hidden; border: 1px solid rgba(255,255,255,0.18);';

        preview.innerHTML = `
          <img src="${e.target.result}" style="width: 100%; height: 100%; object-fit: cover;">
          <button type="button" class="remove-photo" data-index="${uploadedFiles.length - 1}" style="position: absolute; top: 2px; right: 2px; width: 20px; height: 20px; border-radius: 50%; background: rgba(0,0,0,0.7); color: #fff; border: none; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        `;

        photoPreview.appendChild(preview);
      };
      reader.readAsDataURL(file);
    });
  }

  // 写真削除
  photoPreview.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-photo')) {
      const index = parseInt(e.target.dataset.index);
      uploadedFiles.splice(index, 1);
      e.target.closest('div').remove();

      // インデックスを再設定
      photoPreview.querySelectorAll('.remove-photo').forEach((btn, i) => {
        btn.dataset.index = i;
      });
    }
  });

  // バリデーション関数
  function showError(elementId, message) {
    const errorElement = container.querySelector(`#${elementId}`);
    errorElement.textContent = message;
    errorElement.style.display = 'block';
  }

  function hideError(elementId) {
    const errorElement = container.querySelector(`#${elementId}`);
    errorElement.style.display = 'none';
  }

  function validateForm() {
    let isValid = true;

    // 緊急度チェック
    const urgency = container.querySelector('input[name="urgency"]:checked');
    if (!urgency) {
      showError('urgency-error', '緊急度を選択してください');
      isValid = false;
    } else {
      hideError('urgency-error');
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      showError('report-type-error', '報告種別を選択してください');
      isValid = false;
    } else {
      hideError('report-type-error');
    }

    // 発生日時チェック
    const datetime = container.querySelector('#occurrence-datetime').value;
    if (!datetime) {
      showError('occurrence-datetime-error', '発生日時を入力してください');
      isValid = false;
    } else {
      const selectedDate = new Date(datetime);
      const now = new Date();
      if (selectedDate > now) {
        showError('occurrence-datetime-error', '発生日時に未来の日付は入力できません');
        isValid = false;
      } else {
        hideError('occurrence-datetime-error');
      }
    }

    // 発生場所チェック
    const location = container.querySelector('#occurrence-location').value.trim();
    if (!location) {
      showError('occurrence-location-error', '発生場所を入力してください');
      isValid = false;
    } else {
      hideError('occurrence-location-error');
    }

    // 緊急事態内容チェック
    const content = container.querySelector('#emergency-content').value.trim();
    if (!content) {
      showError('emergency-content-error', '緊急事態内容を入力してください');
      isValid = false;
    } else if (content.length > 1000) {
      showError('emergency-content-error', '文字数上限を超えています');
      isValid = false;
    } else {
      hideError('emergency-content-error');
    }

    // 連絡先電話番号チェック
    const phone = container.querySelector('#contact-phone').value.trim();
    if (!phone) {
      showError('contact-phone-error', '連絡先電話番号を入力してください');
      isValid = false;
    } else if (!/^0\d{1,4}-\d{1,4}-\d{4}$/.test(phone)) {
      showError('contact-phone-error', '正しい電話番号の形式で入力してください');
      isValid = false;
    } else {
      hideError('contact-phone-error');
    }

    return isValid;
  }

  // フォーム送信処理
  const form = container.querySelector('#emergency-form');
  const submitBtn = container.querySelector('#btn-submit');
  const draftBtn = container.querySelector('#btn-draft');
  const completeBtn = container.querySelector('#btn-complete');
  const successMessage = container.querySelector('#success-message');

  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      const formData = {
        緊急度: container.querySelector('input[name="urgency"]:checked').value,
        報告種別: container.querySelector('#report-type').value,
        発生日時: container.querySelector('#occurrence-datetime').value,
        発生場所: container.querySelector('#occurrence-location').value,
        作業項目ID: container.querySelector('#work-item').value || null,
        緊急事態内容: container.querySelector('#emergency-content').value,
        報告者名: container.querySelector('#reporter-name').value,
        連絡先電話番号: container.querySelector('#contact-phone').value,
        添付画像数: uploadedFiles.length,
        報告日時: new Date().toISOString(),
        状態: '送信済み'
      };

      // 緊急報告を保存（異常値検出ログテーブルを使用）
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: crypto.randomUUID(),
        ユーザーID: currentUser?.ユーザーID || crypto.randomUUID(),
        異常値種別: formData.報告種別,
        検出項目: '緊急報告',
        検出値: formData.緊急事態内容,
        閾値: formData.緊急度,
        重要度: formData.緊急度,
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: formData.報告日時,
        作成日時: formData.報告日時,
        更新日時: formData.報告日時
      });

      if (saved) {
        // 成功メッセージを表示
        form.style.display = 'none';
        successMessage.style.display = 'block';
        completeBtn.style.display = 'inline-block';

        // 下書きデータをクリア
        localStorage.removeItem('emergency_report_draft');
      }
    } catch (error) {
      alert('報告の送信に失敗しました。もう一度お試しください。');
      console.error('送信エラー:', error);
    }
  });

  // 下書き保存
  draftBtn.addEventListener('click', () => {
    const draftData = {
      urgency: container.querySelector('input[name="urgency"]:checked')?.value || '',
      reportType: container.querySelector('#report-type').value,
      datetime: container.querySelector('#occurrence-datetime').value,
      location: container.querySelector('#occurrence-location').value,
      workItem: container.querySelector('#work-item').value,
      content: container.querySelector('#emergency-content').value,
      phone: container.querySelector('#contact-phone').value,
      savedAt: new Date().toISOString()
    };

    localStorage.setItem('emergency_report_draft', JSON.stringify(draftData));
    alert('下書きを保存しました');
  });

  // 報告完了ボタン
  completeBtn.addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 下書きデータの復元
  function loadDraft() {
    const draft = localStorage.getItem('emergency_report_draft');
    if (draft) {
      try {
        const data = JSON.parse(draft);
        if (data.urgency) {
          container.querySelector(`input[name="urgency"][value="${data.urgency}"]`).checked = true;
        }
        container.querySelector('#report-type').value = data.reportType || '';
        container.querySelector('#occurrence-datetime').value = data.datetime || '';
        container.querySelector('#occurrence-location').value = data.location || '';
        container.querySelector('#work-item').value = data.workItem || '';
        container.querySelector('#emergency-content').value = data.content || '';
        container.querySelector('#contact-phone').value = data.phone || '';

        // 文字数カウンターを更新
        const length = data.content?.length || 0;
        charCount.textContent = `${length}/1000`;
      } catch (error) {
        console.error('下書きの復元に失敗:', error);
      }
    }
  }

  // 初期化処理
  async function init() {
    await loadCurrentUser();
    await loadWorkItems();
    loadDraft();

    // 現在日時を設定
    const now = new Date();
    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
    container.querySelector('#occurrence-datetime').value = now.toISOString().slice(0, 16);
  }

  init();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let workItems = [];
  let workRecords = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録を読み込み
      const records = await window.aivicApi.list(1); // 作業記録テーブル
      if (records) {
        workRecords = records;
        renderWorkRecordOptions();
      }

      // 作業項目マスタを読み込み
      const items = await window.aivicApi.list(3); // 作業項目マスタテーブル
      if (items) {
        workItems = items.filter(item => item.有効フラグ);
        renderWorkItemOptions();
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業記録選択肢を描画
  function renderWorkRecordOptions() {
    const select = container.querySelector('#select-work-record');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID;
      const date = new Date(record.作業日).toLocaleDateString('ja-JP');
      option.textContent = `${date} - ${record.プロジェクト名} (${record.作業種別})`;
      select.appendChild(option);
    });
  }

  // 作業項目選択肢を描画
  function renderWorkItemOptions() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      select.appendChild(option);
    });
  }

  // 時間計算
  function calculateTime() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#display-total-time').value = '';
      container.querySelector('#display-net-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}:00`);
    let end = new Date(`2000-01-01T${endTime}:00`);

    // 24時間跨ぎの場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - breakTime);

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector('#display-total-time').value = `${totalHours}時間${totalMins}分`;
    container.querySelector('#display-net-time').value = `${netHours}時間${netMins}分`;

    validateTime();
  }

  // バリデーション
  function validateTime() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    hideError();
    hideWarning();

    if (!startTime || !endTime) return true;

    const start = new Date(`2000-01-01T${startTime}:00`);
    let end = new Date(`2000-01-01T${endTime}:00`);

    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);

    // 同一時刻チェック
    if (startTime === endTime) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    // 中断時間が作業時間を超過チェック
    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています');
      return false;
    }

    // 異常な作業時間の警告（12時間以上）
    if (totalMinutes > 720) {
      showWarning('作業時間が12時間を超えています。確認してください。');
    }

    return true;
  }

  function showError(message) {
    const errorArea = container.querySelector('#error-area');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorArea.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-area').classList.add('hidden');
  }

  function showWarning(message) {
    const warningArea = container.querySelector('#warning-area');
    const warningMessage = container.querySelector('#warning-message');
    warningMessage.textContent = message;
    warningArea.classList.remove('hidden');
  }

  function hideWarning() {
    container.querySelector('#warning-area').classList.add('hidden');
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      currentWorkRecord = null;
      clearForm();
      return;
    }

    currentWorkRecord = workRecords.find(r => r.作業記録ID === recordId);
    if (currentWorkRecord) {
      populateForm(currentWorkRecord);
    }
  });

  function clearForm() {
    container.querySelector('#input-work-date').value = '';
    container.querySelector('#input-start-time').value = '';
    container.querySelector('#input-end-time').value = '';
    container.querySelector('#input-break-time').value = '';
    container.querySelector('#select-work-item').value = '';
    container.querySelector('#textarea-work-detail').value = '';
    container.querySelector('#input-correction-reason').value = '';
    container.querySelector('#display-total-time').value = '';
    container.querySelector('#display-net-time').value = '';
    hideError();
    hideWarning();
  }

  function populateForm(record) {
    const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
    container.querySelector('#input-work-date').value = workDate;

    if (record.作業開始時刻) {
      const startTime = new Date(record.作業開始時刻);
      container.querySelector('#input-start-time').value = 
        startTime.getHours().toString().padStart(2, '0') + ':' + 
        startTime.getMinutes().toString().padStart(2, '0');
    }

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      container.querySelector('#input-end-time').value = 
        endTime.getHours().toString().padStart(2, '0') + ':' + 
        endTime.getMinutes().toString().padStart(2, '0');
    }

    container.querySelector('#textarea-work-detail').value = record.作業内容 || '';

    // 中断時間を計算（中断記録テーブルから取得する想定だが、簡略化のため0とする）
    container.querySelector('#input-break-time').value = '0';

    calculateTime();
  }

  // 時間入力時の計算
  container.querySelector('#input-start-time').addEventListener('change', calculateTime);
  container.querySelector('#input-end-time').addEventListener('change', calculateTime);
  container.querySelector('#input-break-time').addEventListener('input', calculateTime);

  // 文字数カウント
  container.querySelector('#textarea-work-detail').addEventListener('input', function() {
    const count = this.value.length;
    container.querySelector('#char-count-detail').textContent = count;
  });

  // 元データ参照
  container.querySelector('#btn-original-data').addEventListener('click', function() {
    if (!currentWorkRecord) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const workDate = new Date(currentWorkRecord.作業日).toLocaleDateString('ja-JP');
    const startTime = currentWorkRecord.作業開始時刻 ? 
      new Date(currentWorkRecord.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '未設定';
    const endTime = currentWorkRecord.作業終了時刻? 
      new Date(currentWorkRecord.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '未設定';

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; font-size: 13px;">
        <div style="color: var(--text-muted);">作業日:</div>
        <div>${workDate}</div>
        <div style="color: var(--text-muted);">開始時刻:</div>
        <div>${startTime}</div>
        <div style="color: var(--text-muted);">終了時刻:</div>
        <div>${endTime}</div>
        <div style="color: var(--text-muted);">プロジェクト:</div>
        <div>${currentWorkRecord.プロジェクト名 || ''}</div>
        <div style="color: var(--text-muted);">作業場所:</div>
        <div>${currentWorkRecord.作業場所 || ''}</div>
        <div style="color: var(--text-muted);">作業種別:</div>
        <div>${currentWorkRecord.作業種別 || ''}</div>
        <div style="color: var(--text-muted);">作業内容:</div>
        <div style="white-space: pre-wrap;">${currentWorkRecord.作業内容 || ''}</div>
        <div style="color: var(--text-muted);">進捗状況:</div>
        <div>${currentWorkRecord.進捗状況 || ''}</div>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').classList.add('hidden');
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen("scr-1778907367889");
  });

  // 保存
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!currentWorkRecord) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    if (!correctionReason) {
      showError('修正理由は必須入力です');
      return;
    }

    if (correctionReason.length > 500) {
      showError('修正理由は500文字以内で入力してください');
      return;
    }

    const workDetail = container.querySelector('#textarea-work-detail').value;
    if (workDetail.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください');
      return;
    }

    if (!validateTime()) {
      return;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const workItemId = container.querySelector('#select-work-item').value;

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください');
      return;
    }

    try {
      // 作業記録を更新
      const updateData = {
        作業開始時刻: new Date(`${currentWorkRecord.作業日.split('T')[0]}T${startTime}:00`).toISOString(),
        作業終了時刻: new Date(`${currentWorkRecord.作業日.split('T')[0]}T${endTime}:00`).toISOString(),
        作業内容: workDetail,
        更新日時: new Date().toISOString()
      };

      const result = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

      if (result) {
        alert('工数修正が完了しました');
        window.showScreen("scr-1778907367889");
      } else {
        showError('保存に失敗しました');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存中にエラーが発生しました');
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentResults = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業員データを読み込み
      const users = await window.aivicApi.list(0) || [];
      const workersSelect = container.querySelector('#select-workers');
      workersSelect.innerHTML = '<option value="">全作業員</option>';
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.ユーザーID;
        option.textContent = user.氏名 || user.ユーザー名;
        workersSelect.appendChild(option);
      });

      // 作業項目データを読み込み
      const workItems = await window.aivicApi.list(3) || [];
      const workItemsSelect = container.querySelector('#select-work-items');
      workItemsSelect.innerHTML = '<option value="">全作業項目</option>';
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = item.作業項目名;
        workItemsSelect.appendChild(option);
      });
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#result-tbody');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">該当するデータが見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(record => `
      <tr data-id="${record.作業記録ID}">
        <td style="padding: 6px 10px; font-size: 12px;">${formatDate(record.作業日) || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${record.作業員名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${formatWorkTime(record.作業時間) || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${record.プロジェクト名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${record.作業場所 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${record.作業種別 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${record.進捗状況 || ''}</td>
      </tr>
    `).join('');
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間フォーマット（分→時間:分）
  function formatWorkTime(minutes) {
    if (!minutes) return '';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // バリデーション
  function validateConditions() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const outputFormat = container.querySelector('input[name="output-format"]:checked');
    const errorDiv = container.querySelector('#error-message');

    errorDiv.classList.add('hidden');

    if (!startDate || !endDate) {
      showError('開始日と終了日を入力してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // プレビュー更新
  function updatePreview() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const workers = Array.from(container.querySelector('#select-workers').selectedOptions).map(o => o.textContent).filter(t => t !== '全作業員');
    const workItems = Array.from(container.querySelector('#select-work-items').selectedOptions).map(o => o.textContent).filter(t => t !== '全作業項目');
    const location = container.querySelector('#input-location').value;
    const excludeAnomaly = container.querySelector('#check-exclude-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;

    const conditions = [];
    if (startDate && endDate) {
      conditions.push(`期間: ${startDate} ～ ${endDate}`);
    }
    if (workers.length > 0) {
      conditions.push(`作業員: ${workers.join(', ')}`);
    }
    if (workItems.length > 0) {
      conditions.push(`作業項目: ${workItems.join(', ')}`);
    }
    if (location) {
      conditions.push(`作業場所: ${location}`);
    }
    if (excludeAnomaly) {
      conditions.push('異常値データを除外');
    }
    if (includeInterruption) {
      conditions.push('中断記録を含む');
    }

    const conditionsDiv = container.querySelector('#preview-conditions');
    conditionsDiv.textContent = conditions.length > 0 ? conditions.join(' / ') : '抽出条件を設定してください';
  }

  // データ抽出実行
  async function executeExtraction() {
    if (!validateConditions()) return;

    try {
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;
      const selectedWorkers = Array.from(container.querySelector('#select-workers').selectedOptions).map(o => o.value).filter(v => v);
      const selectedWorkItems = Array.from(container.querySelector('#select-work-items').selectedOptions).map(o => o.value).filter(v => v);
      const location = container.querySelector('#input-location').value;
      const excludeAnomaly = container.querySelector('#check-exclude-anomaly').checked;
      const includeInterruption = container.querySelector('#check-include-interruption').checked;
      const outputFormat = container.querySelector('input[name="output-format"]:checked').value;

      // 作業記録データを取得
      let workRecords = await window.aivicApi.list(1) || [];
      const users = await window.aivicApi.list(0) || [];

      // 作業員名を結合
      workRecords = workRecords.map(record => {
        const user = users.find(u => u.ユーザーID === record.作業員ID);
        return {
          ...record,
          作業員名: user ? (user.氏名 || user.ユーザー名) : ''
        };
      });

      // フィルタリング
      let filteredRecords = workRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        const start = new Date(startDate);
        const end = new Date(endDate);

        if (recordDate < start || recordDate > end) return false;

        if (selectedWorkers.length > 0 && !selectedWorkers.includes(record.作業員ID)) return false;

        if (location && !record.作業場所?.includes(location)) return false;

        return true;
      });

      // 異常値除外
      if (excludeAnomaly) {
        filteredRecords = filteredRecords.filter(record => {
          const workTime = record.作業時間 || 0;
          return workTime > 0 && workTime <= 1440; // 0分～24時間の範囲
        });
      }

      // 中断記録処理
      if (includeInterruption) {
        const interruptions = await window.aivicApi.list(2) || [];
        // 中断記録も結果に含める処理（簡略化）
      }

      currentResults = filteredRecords;
      renderResults(currentResults);

      // データ件数更新
      const countDiv = container.querySelector('#preview-count');
      countDiv.textContent = `データ件数: ${currentResults.length}件`;

      // データエクスポート
      if (outputFormat === 'csv') {
        exportToCSV(currentResults);
      } else if (outputFormat === 'excel') {
        exportToExcel(currentResults);
      }

    } catch (error) {
      console.error('抽出エラー:', error);
      showError('データ抽出中にエラーが発生しました');
    }
  }

  // CSV エクスポート
  function exportToCSV(data) {
    const headers = ['作業日', '作業員', '作業時間', 'プロジェクト', '作業場所', '作業種別', '進捗状況'];
    const csvContent = [
      headers.join(','),
      ...data.map(record => [
        formatDate(record.作業日),
        record.作業員名,
        formatWorkTime(record.作業時間),
        record.プロジェクト名,
        record.作業場所,
        record.作業種別,
        record.進捗状況
      ].map(field => `"${(field || '').toString().replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // Excel エクスポート（CSV形式だが拡張子をxlsxに）
  function exportToExcel(data) {
    const headers = ['作業日', '作業員', '作業時間', 'プロジェクト', '作業場所', '作業種別', '進捗状況'];
    const csvContent = [
      headers.join(','),
      ...data.map(record => [
        formatDate(record.作業日),
        record.作業員名,
        formatWorkTime(record.作業時間),
        record.プロジェクト名,
        record.作業場所,
        record.作業種別,
        record.進捗状況
      ].map(field => `"${(field || '').toString().replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.xlsx`;
    link.click();
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-workers').selectedIndex = 0;
    container.querySelector('#select-work-items').selectedIndex = 0;
    container.querySelector('#input-location').value = '';
    container.querySelector('#check-exclude-anomaly').checked = false;
    container.querySelector('#check-include-interruption').checked = false;
    container.querySelectorAll('input[name="output-format"]').forEach(radio => radio.checked = false);

    updatePreview();

    const countDiv = container.querySelector('#preview-count');
    countDiv.textContent = 'データ件数: -';

    renderResults([]);
  }

  // イベントリスナー設定
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector('#btn-preview').addEventListener('click', updatePreview);

  container.querySelector('#btn-extract').addEventListener('click', executeExtraction);

  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    container.querySelector('#save-condition-dialog').classList.remove('hidden');
  });

  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    container.querySelector('#save-condition-dialog').classList.add('hidden');
    container.querySelector('#input-condition-name').value = '';
  });

  container.querySelector('#btn-confirm-save').addEventListener('click', () => {
    const conditionName = container.querySelector('#input-condition-name').value;
    if (conditionName) {
      // 条件保存処理（簡略化）
      alert('条件が保存されました');
      container.querySelector('#save-condition-dialog').classList.add('hidden');
      container.querySelector('#input-condition-name').value = '';
    }
  });

  // 条件変更時のプレビュー自動更新
  ['#input-start-date', '#input-end-date', '#select-workers', '#select-work-items', '#input-location', '#check-exclude-anomaly', '#check-include-interruption'].forEach(selector => {
    const element = container.querySelector(selector);
    if (element) {
      element.addEventListener('change', updatePreview);
    }
  });

  // 初期化
  loadInitialData();
  updatePreview();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#records-tbody');
  const recordCount = container.querySelector('#record-count');
  const detailModal = container.querySelector('#detail-modal');
  let currentRecordId = null;
  let allRecords = [];
  let users = [];
  let breakRecords = [];
  let anomalyLogs = [];

  // ユーザー情報とその他データを取得
  async function loadRelatedData() {
    try {
      users = await window.aivicApi.list(0) || []; // ユーザー
      breakRecords = await window.aivicApi.list(2) || []; // 中断記録
      anomalyLogs = await window.aivicApi.list(4) || []; // 異常値検出ログ
    } catch (error) {
      console.error('関連データの取得に失敗:', error);
    }
  }

  // 時刻フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算関数
  function calculateWorkTime(startTime, endTime, breakTime = 0) {
    if (!startTime || !endTime) return 0;
    const start = new Date(startTime);
    const end = new Date(endTime);
    const diffMinutes = Math.floor((end - start) / (1000 * 60)) - breakTime;
    return Math.max(0, diffMinutes);
  }

  // 時間表示フォーマット関数
  function formatDuration(minutes) {
    if (!minutes || minutes === 0) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}分`;
    if (mins === 0) return `${hours}時間`;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック関数
  function hasAnomaly(recordId) {
    return anomalyLogs.some(log => 
      log.検出対象レコードID === recordId && 
      log.確認状況 === '未確認'
    );
  }

  // 中断時間計算関数
  function calculateBreakTime(recordId) {
    const breaks = breakRecords.filter(br => br.作業記録ID === recordId);
    return breaks.reduce((total, br) => total + (br.中断時間 || 0), 0);
  }

  // ユーザー名取得関数
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.氏名 : '不明';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    allRecords = rows;
    recordCount.textContent = `${rows.length}件`;

    if (rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 20px;">記録なし</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(record => {
      const breakTime = calculateBreakTime(record.作業記録ID);
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);
      const hasAnomalyFlag = hasAnomaly(record.作業記録ID);
      const userName = getUserName(record.作業員ID);

      // 承認状態に応じたボタンの表示制御
      const isApproved = record.承認状態 === '承認済み';
      const canEdit = !isApproved;
      const canApprove = record.承認状態 === '未承認';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${formatDate(record.作業日)}</td>
          <td>${userName}</td>
          <td>${formatTime(record.作業開始時刻)}</td>
          <td>${formatTime(record.作業終了時刻)}</td>
          <td>${formatDuration(workTime)} ${hasAnomalyFlag ? '<span style="color: #ff6a00; font-weight: bold;" title="異常値検出">⚠</span>' : ''}</td>
          <td>${formatDuration(breakTime)}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
              ${record.承認状態 === '承認済み' ? 'background: rgba(34, 197, 94, 0.2); color: #22c562;' : 
                record.承認状態 === '差し戻し' ? 'background: rgba(239, 68, 68, 0.2); color: #ef4444;' : 
                'background: rgba(251, 191, 36, 0.2); color: #fbbf24;'}">
              ${record.承認状態}
            </span>
          </td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 12px; margin-right: 4px;">詳細</button>
            ${canEdit ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 12px; margin-right: 4px;">修正</button>` : ''}
            ${canApprove ? `<button class="action-btn approve-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 12px; margin-right: 4px;">承認</button>` : ''}
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 12px; background: rgba(239, 68, 68, 0.1); color: #ef4444; border-color: rgba(239, 68, 68, 0.3);">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示関数
  function showDetail(recordId) {
    const record = allRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    currentRecordId = recordId;
    const breakTime = calculateBreakTime(recordId);
    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);
    const userName = getUserName(record.作業員ID);

    container.querySelector('#detail-work-date').textContent = formatDate(record.作業日);
    container.querySelector('#detail-worker-name').textContent = userName;
    container.querySelector('#detail-start-time').textContent = formatTime(record.作業開始時刻);
    container.querySelector('#detail-end-time').textContent = formatTime(record.作業終了時刻);
    container.querySelector('#detail-work-time').textContent = formatDuration(workTime);
    container.querySelector('#detail-approval-status').textContent = record.承認状態;
    container.querySelector('#detail-work-content').textContent = record.作業内容 || '';
    container.querySelector('#detail-remarks').textContent = record.備考 || '';

    // ボタンの表示制御
    const isApproved = record.承認状態 === '承認済み';
    const editBtn = container.querySelector('#btn-modal-edit');
    const approveBtn = container.querySelector('#btn-modal-approve');

    if (isApproved) {
      editBtn.style.display = 'none';
      approveBtn.style.display = 'none';
    } else {
      editBtn.style.display = 'inline-block';
      approveBtn.style.display = record.承認状態 === '未承認' ? 'inline-block' : 'none';
    }

    detailModal.classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    if (allRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '実働時間(分)', '中断時間(分)', '作業内容', '作業場所', '承認状態', '備考'];
    const csvData = allRecords.map(record => {
      const breakTime = calculateBreakTime(record.作業記録ID);
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻, breakTime);
      const userName = getUserName(record.作業員ID);

      return [
        formatDate(record.作業日),
        userName,
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        workTime,
        breakTime,
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        `"${(record.作業場所 || '').replace(/"/g, '""')}"`,
        record.承認状態,
        `"${(record.備考 || '').replace(/"/g, '""')}"`
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化処理
  async function initialize() {
    await loadRelatedData();
    const initialRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
    renderRows(initialRecords);
  }

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const workDate = container.querySelector('#input-work-date').value;
    const dateFrom = container.querySelector('#input-date-from').value;
    const dateTo = container.querySelector('#input-date-to').value;

    // 日付範囲の妥当性チェック
    if (dateFrom && dateTo && new Date(dateFrom) > new Date(dateTo)) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    try {
      const allRows = await window.aivicApi.list(1) || [];
      let filteredRows = allRows;

      if (workDate) {
        filteredRows = filteredRows.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate === workDate;
        });
      }

      if (dateFrom) {
        filteredRows = filteredRows.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate >= dateFrom;
        });
      }

      if (dateTo) {
        filteredRows = filteredRows.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate <= dateTo;
        });
      }

      renderRows(filteredRows);
    } catch (error) {
      console.error('検索エラー:', error);
      alert('検索中にエラーが発生しました');
    }
  });

  // CSVエクスポートボタンのイベントリスナー
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // モーダル関連のイベントリスナー
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    detailModal.classList.add('hidden');
  });

  container.querySelector('#btn-modal-close').addEventListener('click', () => {
    detailModal.classList.add('hidden');
  });

  container.querySelector('#btn-modal-edit').addEventListener('click', () => {
    if (currentRecordId) {
      window.showScreen("scr-1778907343735");
    }
  });

  container.querySelector('#btn-modal-approve').addEventListener('click', async () => {
    if (!currentRecordId) return;

    if (!confirm('この記録を承認しますか？')) return;

    try {
      await window.aivicApi.update(1, currentRecordId, {
        承認状態: '承認済み',
        承認者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
        承認日時: new Date().toISOString()
      });

      detailModal.classList.add('hidden');
      const updatedRecords = await window.aivicApi.list(1);
      renderRows(updatedRecords);
      alert('承認が完了しました');
    } catch (error) {
      console.error('承認エラー:', error);
      alert('承認中にエラーが発生しました');
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const editBtn = e.target.closest('.edit-btn');
    const approveBtn = e.target.closest('.approve-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }

    if (editBtn) {
      window.showScreen("scr-1778907343735");
    }

    if (approveBtn) {
      if (!confirm('この記録を承認しますか？')) return;

      try {
        await window.aivicApi.update(1, approveBtn.dataset.id, {
          承認状態: '承認済み',
          承認者ID: 'current-user-id',
          承認日時: new Date().toISOString()
        });

        const updatedRecords = await window.aivicApi.list(1);
        renderRows(updatedRecords);
        alert('承認が完了しました');
      } catch (error) {
        console.error('承認エラー:', error);
        alert('承認中にエラーが発生しました');
      }
    }

    if (deleteBtn) {
      if (!confirm('この記録を削除しますか？')) return;

      try {
        await window.aivicApi.delete(1, deleteBtn.dataset.id);
        const updatedRecords = await window.aivicApi.list(1);
        renderRows(updatedRecords);
        alert('記録を削除しました');
      } catch (error) {
        console.error('削除エラー:', error);
        alert('削除中にエラーが発生しました');
      }
    }
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add('hidden');
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  // 現在のユーザーID（実際の実装では認証から取得）
  const currentUserId = 'user-001';

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目名;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          option.dataset.standardHours = item.標準工数時間 || 0;
          select.appendChild(option);
        });
    }
  }

  // 工数時間の自動計算
  function calculateWorkHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const calculatedField = container.querySelector('#calculated-hours');

    if (!startTime || !endTime) {
      calculatedField.value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}:00`);
    let end = new Date(`2000-01-01T${endTime}:00`);

    // 終了時刻が開始時刻より前の場合は翌日とみなす
    if (end <= start) {
      end = new Date(`2000-01-02T${endTime}:00`);
    }

    const diffMs = end.getTime() - start.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const workMinutes = Math.max(0, diffMinutes - breakTime);
    const workHours = (workMinutes / 60).toFixed(1);

    calculatedField.value = `${workHours}h`;
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#work-date').value;
    const projectName = container.querySelector('#project-name').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workContent = container.querySelector('#work-content').value.trim();

    // 必須項目チェック
    if (!workDate) errors.push('作業日付を選択してください');
    if (!projectName) errors.push('プロジェクト名を選択してください');
    if (!workItem) errors.push('作業項目を選択してください');
    if (!workLocation) errors.push('作業場所を入力してください');
    if (!startTime) errors.push('開始時刻を入力してください');
    if (!endTime) errors.push('終了時刻を入力してください');
    if (!workContent) errors.push('作業内容詳細を入力してください');

    // 未来日付チェック
    if (workDate) {
      const today = new Date();
      const selectedDate = new Date(workDate);
      today.setHours(0, 0, 0, 0);
      selectedDate.setHours(0, 0, 0, 0);
      if (selectedDate > today) {
        errors.push('未来日付は選択できません');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      let end = new Date(`2000-01-01T${endTime}:00`);

      // 同日内での開始時刻 > 終了時刻チェック
      if (end <= start && workDate) {
        const workDateObj = new Date(workDate);
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        workDateObj.setHours(0, 0, 0, 0);

        // 当日の場合のみエラー（日付跨ぎは許可）
        if (workDateObj.getTime() === today.getTime()) {
          errors.push('開始時刻が終了時刻より後になっています');
        }
      }

      // 24時間以上チェック
      if (end <= start) {
        end = new Date(`2000-01-02T${endTime}:00`);
      }
      const diffMs = end.getTime() - start.getTime();
      const diffHours = diffMs / (1000 * 60 * 60);
      if (diffHours >= 24) {
        errors.push('24時間以上の作業時間は入力できません');
      }

      // 中断時間チェック
      const workMinutes = Math.floor(diffMs / (1000 * 60));
      if (breakTime >= workMinutes) {
        errors.push('中断時間は作業時間を超過できません');
      }
    }

    // 文字数チェック
    if (workContent.length > 1000) {
      errors.push('作業内容詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    const errorContainer = container.querySelector('#error-messages');
    const errorList = container.querySelector('#error-list');

    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `<li>${error}</li>`).join('');
      errorContainer.style.display = 'block';
    } else {
      errorContainer.style.display = 'none';
    }
  }

  // 成功メッセージ表示
  function showSuccess() {
    const successContainer = container.querySelector('#success-message');
    successContainer.style.display = 'block';
    setTimeout(() => {
      successContainer.style.display = 'none';
    }, 3000);
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#work-record-form').reset();
    container.querySelector('#worker-name').value = '田中太郎';
    container.querySelector('#calculated-hours').value = '';
    container.querySelector('#content-counter').textContent = '0';
    showErrors([]);
  }

  // 作業記録保存
  async function saveWorkRecord(isDraft = false) {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return false;
    }

    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    // 作業時間計算
    const start = new Date(`${workDate}T${startTime}:00`);
    let end = new Date(`${workDate}T${endTime}:00`);
    if (end <= start) {
      end = new Date(start.getTime() + 24 * 60 * 60 * 1000);
      end.setHours(parseInt(endTime.split(':')[0]), parseInt(endTime.split(':')[1]), 0, 0);
    }
    const workMinutes = Math.floor((end.getTime() - start.getTime()) / (1000 * 60)) - breakTime;

    const recordData = {
      作業員ID: currentUserId,
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: start.toISOString(),
      作業終了時刻: end.toISOString(),
      作業時間: workMinutes,
      プロジェクト名: container.querySelector('#project-name').value,
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item').value,
      作業内容: container.querySelector('#work-content').value.trim(),
      進捗状況: isDraft ? '一時保存' : '完了',
      備考: container.querySelector('#work-notes').value.trim(),
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUserId
    };

    const saved = await window.aivicApi.save(1, recordData); // 作業記録テーブル
    if (saved) {
      showSuccess();
      if (!isDraft) {
        clearForm();
      }
      return true;
    }
    return false;
  }

  // 初期化
  loadWorkItems();

  // 今日の日付を初期値に設定
  const today = new Date();
  container.querySelector('#work-date').value = today.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#end-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#break-time').addEventListener('input', calculateWorkHours);

  // 文字数カウンター
  container.querySelector('#work-content').addEventListener('input', function() {
    const counter = container.querySelector('#content-counter');
    counter.textContent = this.value.length;
  });

  // フォーム送信
  container.querySelector('#work-record-form').addEventListener('submit', async function(e) {
    e.preventDefault();
    await saveWorkRecord(false);
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async function() {
    await saveWorkRecord(true);
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // 中断時間記録ボタン
  container.querySelector('#btn-add-break').addEventListener('click', function() {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  });

  // ボタンホバー効果
  container.querySelector('#btn-register').addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#btn-register').addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  const secondaryButtons = container.querySelectorAll('.action-btn.secondary');
  secondaryButtons.forEach(btn => {
    btn.addEventListener('mouseenter', function() {
      this.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', function() {
      this.style.background = 'transparent';
    });
  });

  // フォーカス効果
  const inputs = container.querySelectorAll('.input');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.style.outline = 'none';
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });
}
